      if(fields.role&&['Employee','Administrator'].includes(fields.role))setValueIfPresent('registerUserType',fields.role);
      setValueIfPresent('registerUserId',fields.user_id);setValueIfPresent('registerCompanyCode',fields.company_code);setValueIfPresent('registerName',fields.name);setValueIfPresent('registerPosition',fields.position);setValueIfPresent('registerEmail',fields.email);
