      if(action==='START_ENROLLMENT'){if($('registerVoiceEnabled'))$('registerVoiceEnabled').checked=true;updateRegisterVoiceUi();setTimeout(()=>recordRegisterVoiceSample(),180);return reply;}
      if(action==='SUBMIT_SIGNUP'){const password=$('registerPassword')?.value||'';if(password)setTimeout(()=>$('controlRegisterForm')?.requestSubmit(),180);else $('registerPassword')?.focus();return password?reply:`${reply} Type your password privately before Zari submits the registration.`;}
      return reply;
