  /* v5.10 — chronological table ordering and functional/departmental authority */
  function temporalValue(row,keys=[]){for(const key of keys){const raw=row?.[key];if(raw===undefined||raw===null||raw==='')continue;const text=String(raw).trim(),value=/^\d{4}-\d{2}$/.test(text)?`${text}-01`:text,t=Date.parse(value);if(Number.isFinite(t))return t;}return 0;}
  function newestFirst(rows,keys=['updatedAt','updated_at','createdAt','created_at','uploadedAt','uploaded_at','decided_at','clock_out_at','clock_in_at','work_date','date','appliedDate','applied_date','openDate','open_date','month','startDate','start_date']){return [...(rows||[])].sort((a,b)=>{const d=temporalValue(b,keys)-temporalValue(a,keys);if(d)return d;return String(b?.id||b?.entryId||b?.employeeId||'').localeCompare(String(a?.id||a?.entryId||a?.employeeId||''));});}
  function functionalAuthority(user=controlUser()||{}){const role=String(user?.role||'Employee'),text=[user?.supervisoryRole,user?.position,user?.department].filter(Boolean).join(' ').toLowerCase();if(role==='Developer')return 'DEVELOPER';if(/\bchief executive officer\b|\bceo\b/.test(text))return 'CEO';if(/internal audit|internal auditor|auditor|audit manager|audit director|head of audit/.test(text))return 'AUDITOR';if(/human resources|human resource|\bhr\b/.test(text)&&/(manager|director|head)/.test(text))return 'HR_MANAGER';if(/finance/.test(text)&&/(manager|director|head)/.test(text))return 'FINANCE_MANAGER';if(/program(?:me)?s?/.test(text)&&/(manager|director|head)/.test(text))return 'PROGRAMS_MANAGER';if(/project/.test(text)&&/(manager|director|head)/.test(text))return 'PROJECT_MANAGER';if(String(user?.supervisoryRole||'')==='Head of Department')return 'HEAD_OF_DEPARTMENT';if(String(user?.supervisoryRole||'')==='Supervisor')return 'SUPERVISOR';if(role==='Administrator')return 'ADMINISTRATOR';return 'EMPLOYEE';}
  function authorityLabel(authority){return ({DEVELOPER:'Developer',CEO:'Chief Executive Officer',AUDITOR:'Auditor / Internal Audit',ADMINISTRATOR:'Administrator',HR_MANAGER:'Human Resources Manager',FINANCE_MANAGER:'Finance Manager',PROJECT_MANAGER:'Project Manager',PROGRAMS_MANAGER:'Programs Manager / Director',HEAD_OF_DEPARTMENT:'Head of Department',SUPERVISOR:'Supervisor',EMPLOYEE:'Employee'})[authority]||'Employee';}
  function effectiveUserOrg(user=controlUser()||{}){const vals=[user?.id,user?.name,user?.email].filter(Boolean).map(x=>String(x).trim().toLowerCase()),employee=(engine.state.employees||[]).find(e=>[e.employeeId,e.name,e.email].filter(Boolean).some(v=>vals.includes(String(v).trim().toLowerCase())));return {...(employee||{}),...(user||{}),department:user?.department||employee?.department||'',supervisor:user?.supervisor||employee?.supervisor||'',position:user?.position||employee?.position||''};}
  function managedEmployeesForUser(user=controlUser()||{}){const u=effectiveUserOrg(user),authority=functionalAuthority(u),cid=String(u.companyId||currentCompanyId()||''),all=(engine.state.employees||[]).filter(e=>!cid||String(e.companyId||cid)===cid);if(['DEVELOPER','CEO','ADMINISTRATOR','HR_MANAGER'].includes(authority))return all;const refs=new Set([u.id,u.name,u.email,u.employeeId].filter(Boolean).map(x=>String(x).trim().toLowerCase())),dept=String(u.department||'').trim().toLowerCase();if(['FINANCE_MANAGER','PROJECT_MANAGER','PROGRAMS_MANAGER','HEAD_OF_DEPARTMENT','SUPERVISOR'].includes(authority))return all.filter(e=>{const sameDept=dept&&String(e.department||'').trim().toLowerCase()===dept,supervisor=String(e.supervisor||'').trim().toLowerCase();return sameDept||refs.has(supervisor)||refs.has(String(e.employeeId||'').trim().toLowerCase());});const self=leaveActorEmployee();return self?[self]:[];}
  function managedEmployeeIdSet(user=controlUser()||{}){const ids=new Set();for(const e of managedEmployeesForUser(user)){for(const v of [e.employeeId,e.employee_id,e.id,e.name,e.email])if(v)ids.add(String(v).trim().toLowerCase());}const u=effectiveUserOrg(user);for(const v of [u.id,u.employeeId,u.name,u.email])if(v)ids.add(String(v).trim().toLowerCase());return ids;}
  function rowEmployeeMatch(row,ids){const vals=[row?.employeeId,row?.employee_id,row?.employee,row?.employee_name,row?.userId,row?.user_id,row?.ownerId,row?.owner_id].filter(Boolean).map(v=>String(v).trim().toLowerCase());return vals.some(v=>ids.has(v));}
  function scopeEmployeeRows(rows,user=controlUser()||{}){const authority=functionalAuthority(effectiveUserOrg(user));if(['DEVELOPER','CEO','ADMINISTRATOR','HR_MANAGER'].includes(authority))return [...(rows||[])];const ids=managedEmployeeIdSet(user);return (rows||[]).filter(r=>rowEmployeeMatch(r,ids)||ids.has(String(r?.employeeId||r?.id||'').trim().toLowerCase()));}
