  function selectionActive105(row){return Boolean(row&&['SELECTED','ONBOARDING_SENT'].includes(String(row.status||'').toUpperCase()));}
  function selectionVisibleApplications105(){let rows=newestFirst(recruitmentBundle().applications||[],['applied_at','updated_at']);if(state.recruitVacancy)rows=rows.filter(a=>String(a.vacancy_id)===String(state.recruitVacancy));return rows;}
  function selectionChosenApplications105(){return selectionVisibleApplications105().filter(a=>selectionActive105(selectionForApplication105(a.id)));}
