  function numericScore105(value){const n=Number(value);if(!Number.isFinite(n)||n<0)return null;if(n<=1)return Math.round(n*100);if(n<=100)return Math.round(n);return null;}
  function interviewScore105(applicationId){const row=selectionEvaluation105(applicationId),a=row?.analysis;if(!a||typeof a!=='object')return null;const containers=[a,a.interview,a.evaluation,a.assessment,a.summary,a.candidate].filter(x=>x&&typeof x==='object');for(const obj of containers){for(const key of ['overall_score','overallScore','performance_score','performanceScore','interview_score','interviewScore','score_percent','scorePercent','percentage']){const score=numericScore105(obj?.[key]);if(score!==null)return score;}}return null;}
  function selectionPerformanceCell105(app){const interview=selectionInterview105(app.id),score=interviewScore105(app.id);if(score!==null)return `<div class="selection-performance"><strong>${score}%</strong><small>Interview evaluation</small></div>`;if(!interview)return '<span class="muted">Not interviewed</span>';const status=String(interview.status||'').toUpperCase();if(status==='COMPLETED')return '<div class="selection-performance"><strong>Completed</strong><small>Score not recorded</small></div>';if(status==='SCHEDULED')return `<div class="selection-performance"><strong>Scheduled</strong><small>${esc(new Date(interview.scheduled_at).toLocaleString())}</small></div>`;return `<div class="selection-performance"><strong>${esc(interview.status||'Interview')}</strong><small>Interview status</small></div>`;}
  function selectionFitCell105(app){const score=numericScore105(app.ai_score);if(score===null)return '<span class="muted">Not reviewed</span>';return `<div class="selection-performance"><strong>${score}%</strong><small>Advisory fit · rank ${esc(app.ai_rank||'—')}</small></div>`;}
  function selectionStatusCell105(app){const s=selectionForApplication105(app.id);if(!s||String(s.status).toUpperCase()==='DESELECTED')return '<span class="employee-status pending">Not selected</span>';if(String(s.status).toUpperCase()==='ONBOARDING_SENT')return '<span class="employee-status active">Sent to onboarding</span>';return '<span class="employee-status active">HR selected</span>';}
  function setSelectionBusy105(active,label=''){recruitSelectionBusy105=Boolean(active);for(const id of ['recruitSelectionsEmail','recruitSelectionsWhatsApp','recruitSelectionsOnboarding']){const b=$(id);if(b)b.disabled=recruitSelectionBusy105;}if(label&&$('recruitSelectionSummary'))$('recruitSelectionSummary').textContent=label;}
