    table.innerHTML=`<thead><tr><th class="selection-check-cell"><input type="checkbox" id="recruitSelectionSelectAll" aria-label="Select all visible applicants" /></th><th>Applicant</th><th>Vacancy / qualification</th><th>AI fit score</th><th>Interview performance</th><th>Application status</th><th>Selection status</th></tr></thead><tbody>${html}</tbody>`;
    const all=$('recruitSelectionSelectAll'),eligible=rows.filter(a=>String(selectionForApplication105(a.id)?.status||'').toUpperCase()!=='ONBOARDING_SENT');if(all){all.checked=Boolean(eligible.length&&eligible.every(a=>selectionActive105(selectionForApplication105(a.id))));all.indeterminate=Boolean(eligible.some(a=>selectionActive105(selectionForApplication105(a.id)))&&!all.checked);all.disabled=!eligible.length;}
