  function selectionMessage105(app,channel){const company=activeCompanyForView()||{},companyName=String(company.name||company.companyName||'the organization').trim()||'the organization',role=String(app.vacancy_title||'the position').trim();const greeting=`Dear ${app.applicant_name||'Candidate'},`;const body=`We are pleased to inform you that you have been selected to progress to the onboarding process for ${role} at ${companyName}. Our Human Resources team will guide you through the next onboarding steps and required documentation.`;return channel==='whatsapp'?`${greeting}\n\n${body}\n\nRegards,\nHuman Resources · ${companyName}`:`${greeting}\n\n${body}\n\nRegards,\nHuman Resources\n${companyName}`;}
