  renderOnboarding=function(){renderOnboardingBeforeSelections105();const select=$('onboardingCandidateSelect');if(!select)return;const eligible=engine.state.candidates.filter(c=>['Selected','Offer Accepted'].includes(c.stage)&&String(c.status||'Active').toLowerCase()!=='hired');select.innerHTML=eligible.length?'<option value="">Select candidate received from Recruitment</option>'+eligible.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(vacancyForCandidate(c)?.title||c.jobTitle||c.stage)} · ${esc(c.stage)}</option>`).join(''):'<option value="">No selected candidates received</option>';const kicker=document.querySelector('#view-onboarding .onboarding-start-bar .section-kicker');if(kicker)kicker.textContent='Recruitment selection → employee master';};

