    let ids=[...new Set(engine.state.timeEntries.filter(e=>(!month||e.month===month)&&(!project||e.projectCode===project)&&e.employeeId).map(e=>e.employeeId))];
    if(!ids.length)ids=engine.state.employees.map(e=>e.employeeId);
    const rows=ids.map(id=>engine.state.employees.find(e=>e.employeeId===id)||{employeeId:id,name:id});
    sel.innerHTML=rows.length?rows.map(e=>`<option value="${esc(e.employeeId)}">${esc(e.name||e.employeeId)} · ${esc(e.employeeId)}</option>`).join(''):'<option value="">No employee recovery records</option>';
