  function studioAgentCard(a={}){const id=String(a.id||`custom-${Date.now()}-${Math.random().toString(16).slice(2,7)}`).replace(/[^a-z0-9_-]/gi,'-').toLowerCase(),route=decisionTreeToText(a.decisionTree,defaultAgentDecisionTree(a));return `<article class="studio-agent-card" data-studio-agent="${esc(id)}"><header><div><small>Specialist</small><input class="studio-agent-name" value="${esc(a.name||'Custom Specialist')}" maxlength="80" /></div><label class="studio-agent-toggle"><input class="studio-agent-enabled" type="checkbox" ${a.enabled!==false?'checked':''}/> Enabled</label></header><label>Routing domains<input class="studio-agent-domains" value="${esc((Array.isArray(a.domains)?a.domains:[]).join(', '))}" placeholder="research, finance, systems" /></label><label>Capabilities / features<input class="studio-agent-capabilities" value="${esc((Array.isArray(a.capabilities)?a.capabilities:[]).join(', '))}" placeholder="analyze, diagnose, export" /></label><label>Specialist instructions<textarea class="studio-agent-instructions" rows="3" maxlength="2200">${esc(a.instructions||'Assist Jivan in this specialist domain while preserving all role, tenant and approval boundaries.')}</textarea></label><details class="studio-agent-route-editor"><summary>Decision route</summary><textarea class="studio-agent-decision-tree" rows="5" maxlength="5000">${esc(route)}</textarea></details><button class="btn micro ghost danger-outline studio-agent-remove" type="button">Remove</button></article>`;}
  function renderJivanStudio(){const section=$('jivanDeveloperStudio');if(!section)return;const allowed=developerStudioAllowed();section.hidden=!allowed||state.jivanConsoleMode==='structure';if(!allowed)return;const c=jivanStudioConfig(),active=state.jivanStudio?.active||{},versions=Array.isArray(state.jivanStudio?.versions)?state.jivanStudio.versions:[],comms=Array.isArray(state.jivanStudio?.communications)?state.jivanStudio.communications:[];$('jivanStudioVersion').textContent=active.version_no?`Active policy v${active.version_no}`:'Developer policy';$('jivanStudioScope').textContent='Developer Jivan only';$('studioApplyScope').value=active.apply_scope||'DEVELOPER_ONLY';$('studioReasoningProfile').value=c.runtime?.reasoningProfile||'ADVANCED_BALANCED';$('studioAutonomy').value=c.runtime?.autonomy||'GUARDED_ADVANCED';$('studioMaxToolSteps').value=Math.max(6,Math.min(30,Number(c.runtime?.maxToolSteps||20)));$('studioSpecialistRouting').checked=c.runtime?.specialistRouting!==false;$('studioBackgroundDelegation').checked=c.runtime?.backgroundDelegation!==false;$('studioAutoDiagnostics').checked=c.runtime?.autoDiagnostics!==false;$('studioMessageDrafting').checked=c.rules?.allowMessageDrafting!==false;$('studioExternalEmail').checked=Boolean(c.rules?.allowExternalEmail);$('studioExternalWhatsApp').checked=Boolean(c.rules?.allowExternalWhatsApp);$('studioExternalCalls').checked=Boolean(c.rules?.allowExternalCalls);$('studioAdditionalRules').value=String(c.rules?.additionalRules||'');if($('studioRootDecisionTree'))$('studioRootDecisionTree').value=decisionTreeToText(c?.decisionTrees?.root,defaultRootDecisionTree());const connectors=c.connectors||{};$('studioEmailFrom').value=connectors.email?.fromAddress||'';$('studioEmailEnabled').checked=Boolean(connectors.email?.enabled);$('studioWhatsAppFrom').value=connectors.whatsapp?.fromNumber||'';$('studioWhatsAppEnabled').checked=Boolean(connectors.whatsapp?.enabled);$('studioVoiceFrom').value=connectors.voice?.fromNumber||'';$('studioVoiceEnabled').checked=Boolean(connectors.voice?.enabled);if($('studioAgentGrid'))$('studioAgentGrid').innerHTML=studioAgentRows().map(studioAgentCard).join('');const enabledAgents=studioAgentRows().filter(a=>a.enabled!==false).length,enabledConnectors=[connectors.email,connectors.whatsapp,connectors.voice].filter(x=>x?.enabled).length;$('studioRuntimeState').textContent=active.status||'ACTIVE';$('studioAgentCount').textContent=String(enabledAgents);$('studioConnectorCount').textContent=String(enabledConnectors);$('studioHealthState').textContent=state.systemHealth?.status||'CHECKING';const status=state.jivanStudioConnectorStatus||{};$('studioEmailSecret').textContent=status.email?.secretConfigured?'API secret configured':'API secret not configured';$('studioWhatsAppSecret').textContent=status.whatsapp?.secretConfigured?'Twilio secrets configured':'Twilio secrets not configured';$('studioVoiceSecret').textContent=status.voice?.secretConfigured?'Twilio secrets configured':'Twilio secrets not configured';$('studioVersionHistory').innerHTML=versions.length?versions.map(v=>`<article><div><b>v${esc(v.version_no)}</b><span>${esc(v.status)} · ${esc(v.apply_scope)}</span></div><small>${esc(v.note||'No version note')} · ${esc(String(v.created_at||'').replace('T',' ').slice(0,19))}</small></article>`).join(''):'<article><small>No Studio versions yet.</small></article>';$('studioCommunicationHistory').innerHTML=comms.length?comms.map(x=>`<article><div><b>${esc(x.channel)}</b><span>${esc(x.status)} · ${esc(x.provider||'')}</span></div><small>${esc(x.recipient||'')} ${x.subject?`· ${esc(x.subject)}`:''} · ${esc(String(x.created_at||'').replace('T',' ').slice(0,19))}</small></article>`).join(''):'<article><small>No external Jivan communications yet.</small></article>';setJivanStudioTab(state.jivanStudioTab||'builder');renderJivanEngineStructure();}
