    $('recruitRefreshApplications')?.addEventListener('click',()=>loadRecruitmentBundle(true).then(()=>{renderRecruiting();refreshControlCenter().catch(()=>{});}).catch(err=>toast(err.message)));$('recruitAiRank')?.addEventListener('click',runRecruitAiFitReview);$('recruitCopyOutreach')?.addEventListener('click',()=>copyRecruitmentLink($('recruitOutreachMessage')?.value||'','Message'));$('recruitSendEmail')?.addEventListener('click',()=>sendRecruitOutreach('email'));$('recruitSendWhatsApp')?.addEventListener('click',()=>sendRecruitOutreach('whatsapp'));$('vacancyLogoInput')?.addEventListener('change',async e=>{try{state.vacancyLogoData=await optimizeProfilePhoto(e.target.files?.[0]);renderVacancyLogoPreview();if(e.target.files?.[0]&&!state.vacancyLogoData)toast('Original logo will be stored in Supabase; this browser cannot preview that format.');}catch(err){state.vacancyLogoData='';renderVacancyLogoPreview();toast(err.message);}});
