  function editVacancy(id){const v=engine.state.vacancies.find(x=>String(x.id)===String(id));if(!v)return;prepareVacancyForm(v);$('vacancyDialog')?.showModal();}
  function deleteVacancy(id){if(!recruitmentHrAllowed())return toast('Human Resources recruitment authority is required.');const v=engine.state.vacancies.find(x=>String(x.id)===String(id));if(!v)return;if(!confirm(`Delete vacancy "${v.title}"? Existing applications remain in the HR application archive.`))return;engine.state.vacancies=engine.state.vacancies.filter(x=>String(x.id)!==String(id));persistLocalLiveState();if(state.recruitVacancy===id)state.recruitVacancy='';renderRecruiting();toast('Vacancy deleted from the active system and public portal.');}
  function autoArchiveExpiredVacancies(){const today=new Date().toISOString().slice(0,10);let changed=false;for(const v of engine.state.vacancies){const close=String(v.closeDate||'').slice(0,10);if(!v.archived&&close&&/^\d{4}-\d{2}-\d{2}$/.test(close)&&close<today){v.status='Closed';v.publicVisible=false;v.archived=true;v.archivedAt=new Date().toISOString();v.updatedAt=v.archivedAt;changed=true;}}if(changed)persistLocalLiveState();return changed;}

  function populateCandidateVacancies(){
    const current=$('candidateVacancyInput')?.value||'';
    const options=engine.state.vacancies.filter(v=>!v.archived&&String(v.status||'Open').toLowerCase()!=='closed').map(v=>`<option value="${esc(v.id)}">${esc(v.title)}${v.department?` · ${esc(v.department)}`:''}</option>`).join('');
    if($('candidateVacancyInput')){$('candidateVacancyInput').innerHTML='<option value="">Select vacancy</option>'+options;if([...$('candidateVacancyInput').options].some(o=>o.value===current))$('candidateVacancyInput').value=current;}
  }
  function prepareCandidateForm(){
    $('candidateForm')?.reset();state.candidatePhotoData='';setProfilePreview('candidatePhotoPreview','','Photo');$('candidateAppliedInput').value=new Date().toISOString().slice(0,10);populateCandidateVacancies();if(state.recruitVacancy)$('candidateVacancyInput').value=state.recruitVacancy;
  }
