  function renderCalendar(){
    const all=engine.calendarAnalysis(), rows=newestFirst(all.filter(x=>x.month===state.month),['updatedAt','createdAt','date']), reviews=rows.filter(x=>x.dailyStatus==='REVIEW'), working=rows.filter(x=>x.standardHours>0), holidays=rows.filter(x=>x.dayType==='Holiday');
    $('calendarKpis').innerHTML=[['Expected hours',num(working.reduce((s,x)=>s+x.standardHours,0)),'Selected month',''],['Recorded hours',num(rows.reduce((s,x)=>s+x.recordedHours,0)),'Finance-approved time',''],['Review days',reviews.length,'Non-zero daily variance',reviews.length?'warn':'good'],['Holidays',holidays.length,'Source-detected holiday markers','']].map(x=>`<article class="kpi-card ${x[3]}"><small>${x[0]}</small><b>${x[1]}</b><span>${x[2]}</span></article>`).join('');
    $('calendarBody').innerHTML=rows.length?rows.map(x=>`<tr><td>${x.date}</td><td>${x.day}</td><td>${x.dayType}</td><td class="num">${num(x.standardHours)}</td><td class="num">${num(x.recordedHours)}</td><td class="num">${num(x.variance)}</td><td>${resultChip(x.dailyStatus)}</td><td class="wrap">${esc(x.holidaySource||'')}</td></tr>`).join(''):'<tr class="empty-row"><td colspan="8"><div class="table-empty"><b>No live calendar data for this month</b><span>Work Activity Hub creates a working-day context automatically, or you can add the official calendar above.</span></div></td></tr>';
    paginateTable('calendarBody',true);
    $('calendarHeatmap').innerHTML=rows.length?rows.map(x=>`<div class="heat-day ${x.standardHours===0?'nonwork':x.dailyStatus.toLowerCase()}"><b>${x.date.slice(-2)} · ${x.day}</b><small>${x.dayType}</small><small>${num(x.recordedHours)} / ${num(x.standardHours)} hrs</small></div>`).join(''):'<div class="empty-state-mini">Waiting for live calendar data.</div>';
    requestAnimationFrame(renderCalendarChart);
  }
  function renderCalendarChart(){
    const rows=engine.calendarAnalysis().filter(x=>x.month===state.month).sort((a,b)=>Math.abs(b.variance)-Math.abs(a.variance)).slice(0,10);
    rows.length?drawHorizontalBars($('varianceChart'),rows.map(x=>x.date.slice(5)),rows.map(x=>x.variance),'#b77412',{zeroLine:true}):drawEmptyChart($('varianceChart'),'No live calendar variance yet');
  }

