    $('checkKpis').innerHTML=[['Model status',c.modelStatus,'Overall critical result',c.modelStatus==='PASS'?'good':c.modelStatus==='FAIL'?'bad':''],['Formula errors',c.formulaErrors,'Model integrity check',c.formulaErrors?'bad':'good'],['Blocked months',c.blockedMonths,'Monthly Engine status',c.blockedMonths?'bad':''],['Configuration',c.configurationStatus,'Payroll input readiness',c.configurationStatus==='COMPLETE'?'good':c.configurationStatus==='REVIEW'?'warn':'']].map(x=>`<article class="kpi-card ${x[3]}"><small>${x[0]}</small><b>${x[1]}</b><span>${x[2]}</span></article>`).join('');
