    if(doc.storageFileId){const stored=await persistentFileBase64(doc.storageFileId,5*1024*1024);fileName=stored.name||fileName;mime=stored.mimeType||mime;base64=stored.base64;}else{if(!doc.data)throw new Error('The selected document does not contain reviewable file data.');const m=String(doc.data).match(/^data:([^;]+);base64,(.*)$/s);if(!m)throw new Error('The stored document format is unavailable for AI analysis.');mime=m[1]||mime;base64=m[2];}
