  async function runJivanBackgroundWorker(){if(jivanTaskBusy||!browserSessionToken||!isClientLeader())return;jivanTaskBusy=true;try{let count=0;while(browserSessionToken&&count<2){const task=await supabaseRpc('assurance_regent_browser_agent_task_claim_next',{p_token:browserSessionToken});if(!task?.id)break;await runOneJivanBackgroundTask(task);count++;}}catch(err){console.warn('Jivan background worker paused:',err);}finally{jivanTaskBusy=false;}}
