          if(!confirm(`${decision==='APPROVE'?'Approve':'Reject'} ${LEAVE_LABELS[request.leave_type]||'leave'} for ${employeeLabel} (${request.start_date} to ${request.end_date})?`))throw new Error('The leave decision was cancelled.');
          setAgentHud(`${decision==='APPROVE'?'Approving':'Rejecting'} leave request…`,'Leave & Work Status');
          await supabaseRpc('assurance_regent_browser_leave_decide',{p_token:browserSessionToken,p_request_id:id,p_action:decision,p_note:String(action.note||'').slice(0,1200)});
          await agentGovernanceAudit('leave_decision',id,'OK',`${decision} leave request for ${employeeLabel} by Jivan on explicit authorized instruction.`,{employee_id:request.employee_id||'',leave_type:request.leave_type||''});state.leaveLoadedAt=0;await loadLeaveData(true);if(state.view==='leave')renderLeave();if($('leaveDashboardKpis'))renderDashboardLeave();toast(`Leave request ${decision==='APPROVE'?'approved':'rejected'}.`);results.push({ok:true,type,request_id:id,decision,employee_name:employeeLabel});
