  async function submitControlDocument(e){e.preventDefault();const form=e.currentTarget,file=$('controlDocumentFile')?.files?.[0];if(!file)return;try{const employeeId=$('controlDocumentEmployee')?.value||'',employee=employeeRecord(employeeId,''),replacementId=$('controlDocumentReplacementId')?.value||'',docId=`DOC-${crypto.randomUUID()}`,stored=await uploadPersistentFile(file,{category:'control-documents',entityType:'control-document',entityId:docId,metadata:{department:$('controlDocumentDepartment')?.value.trim()||employee?.department||'',projectCode:$('controlDocumentProject')?.value||'',employeeId}}),payload={companyId:currentCompanyId(),name:file.name,type:file.type||'application/octet-stream',size:file.size,data:'',storageFileId:stored.fileId,storagePath:stored.path,department:$('controlDocumentDepartment')?.value.trim()||employee?.department||'',projectCode:$('controlDocumentProject')?.value||'',employeeId,employeeName:employee?.name||'',source:$('controlDocumentSource')?.value.trim()||'Control Center',uploadedBy:controlUser()?.name||'',replacesDocumentId:replacementId||undefined};const c=localControlStore(),now=new Date().toISOString(),previous=replacementId?(c.documents||[]).find(x=>String(x.id)===String(replacementId)):null,row={id:docId,...payload,status:'PENDING_REVIEW',revision:Number(previous?.revision||0)+1,analysisStatus:'DIRECT_SUPABASE_STORAGE',analysisSummary:'Stored in private Supabase Storage and ready for review.',createdAt:now,uploadedAt:now};c.documents=Array.isArray(c.documents)?c.documents:[];if(previous){previous.status='REPLACED';previous.reworkCompletedAt=now;previous.reworkStatus='REPLACED';}c.documents.unshift(row);saveLocalControlStore(c);if($('controlDocumentDialog')?.open)$('controlDocumentDialog').close();form?.reset();if($('controlDocumentReplacementId'))$('controlDocumentReplacementId').value='';toast(replacementId?'Replacement document stored in Supabase and submitted for review.':'Document stored in Supabase and added to the review inbox.');await refreshControlCenter();openControlPanel('documents');}catch(err){toast(err?.message||'Could not store document.');}}
