    $('reviewList').querySelectorAll('[data-review-action]').forEach(b=>b.addEventListener('click',()=>runControlReview(decodeURIComponent(b.dataset.reviewId),b.dataset.reviewAction)));$('reviewList').querySelectorAll('[data-review-open]').forEach(b=>b.addEventListener('click',()=>{const v=b.dataset.reviewOpen;if(v==='documents')openControlPanel('documents');else{closeControlDrawer();switchView(v);}}));
