  async function runControlReview(id,action){
    const review=(state.control?.reviews||[]).find(x=>x.id===id);if(!review)return;if(!reviewAllowedForUser(review,controlUser(),state.control))return toast('This review is outside your departmental authority.');if(STANDALONE_MODE&&review.kind==='AGENT_ACTION')return toast('Jivan reviews are not active in this Supabase-only edition.');try{
      if(review.kind==='AGENT_ACTION'&&review.approvalState){const approved=action==='approve',r=await apiFetch('/api/brain/resume',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approval_state:review.approvalState,decisions:(review.approvals||[]).map(()=>approved),actor_id:controlActorId()})}),b=await r.json();if(!r.ok)throw new Error(b.error||'Could not resume Jivan.');await apiFetch(`/api/control-center/reviews/${encodeURIComponent(id)}/resolve`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({decision:action,actorId:controlActorId()})});addMessage('assistant',b.output_text||'Agent review completed.');if($('approvalDialog')?.open)$('approvalDialog').close();if(b.requires_approval){const again={...b,text:b.output_text};await registerAgentReview(again);pendingApproval=again;}else pendingApproval=null;
      }else if(STANDALONE_MODE){if(review.kind==='TIME_EVIDENCE'){const row=engine.state.timeEntries.find(x=>x.entryId===review.sourceRef);if(row)row.status=action==='approve'?(review.stage==='SUPERVISOR'?'Supervisor approved':'Finance approved'):'Rejected';persistLocalLiveState();}else if(review.kind==='PAYROLL_CONFIGURATION'){const [month,employeeId]=String(review.sourceRef||'').split('__'),row=engine.state.payroll.find(x=>String(x.month)===month&&String(x.employeeId)===employeeId);if(row){row.configurationStatus=action==='approve'?'COMPLETE':'REVIEW';row.notes=`${action==='approve'?'Approved':'Rejected'} by ${controlUser()?.name||controlActorId()} on ${new Date().toISOString()}${row.notes?` · ${row.notes}`:''}`;row.updatedAt=new Date().toISOString();persistLocalLiveState();}}else if(review.kind==='DOCUMENT'){const c=localControlStore(),d=c.documents.find(x=>x.id===review.sourceRef);if(d){d.status=action==='approve'?'APPROVED':'REJECTED';if(action==='approve')d.archivePath=`${d.department||'Unassigned Department'} / ${d.projectCode||'Unassigned Project'} / ${d.employeeId||d.employeeName||'Unassigned Employee'}`;saveLocalControlStore(c);}}else if(review.kind==='CONTROL_BLOCK'){const c=localControlStore();c.reviewResolutions=c.reviewResolutions||{};c.reviewResolutions[review.id]={action,at:new Date().toISOString(),by:controlActorId()};saveLocalControlStore(c);toast('Blocker acknowledged. Resolve its source control before posting.');}}
      else{const r=await apiFetch(`/api/control-center/reviews/${encodeURIComponent(id)}/action`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,actorId:controlActorId()})}),b=await r.json();if(!r.ok)throw new Error(b.error||'Review action failed.');}
      toast(action==='approve'?'Approved.':action==='reject'?'Rejected.':'Review acknowledged.');await loadLiveState();await refreshControlCenter();populateMonths();refreshCurrent();
    }catch(err){toast(err.message);}
  }

  async function loadIntelligenceStatus(){
    if(STANDALONE_MODE){let status={configured:false,model:'Supabase Edge Function'};try{if(browserSessionToken)status=await supabaseFunction('recovery-agent',{mode:'status'});}catch(err){console.warn('Jivan status check failed.',err);}state.intelligence={enabled:Boolean(status.configured),quality:'DIRECT_SUPABASE_EDGE',openai:{configured:Boolean(status.configured),model:status.model||'Supabase Edge Function'},featureStore:{},metrics:{}};if(state.control)state.control.brain={...(state.control.brain||{}),reasoningMode:status.configured?'OPENAI_RESPONSES_API':'LLM_NOT_CONFIGURED',contextAwareConversation:true,causalReasoning:true,deterministicMath:false,predictiveCompose:false,proactiveAdvice:false,taskExecution:true,visibleUiActivity:true,roleGuardrails:true,voiceInteraction:true};renderIntelligenceSettings();return state.intelligence;}
    try{const r=await apiFetch('/api/intelligence/status');if(!r.ok)throw new Error('Could not load intelligence status.');state.intelligence=await r.json();renderIntelligenceSettings();return state.intelligence;}catch(err){console.warn(err);state.intelligence={enabled:false,quality:'UNAVAILABLE',openai:{configured:false,model:'Unavailable'},featureStore:{},metrics:{}};renderIntelligenceSettings();return state.intelligence;}
  }
  function renderIntelligenceSettings(){
    const i=state.intelligence||{},o=i.openai||{},f=i.featureStore||{},m=i.metrics||{},grid=$('intelligenceStatusGrid');if(!grid)return;
    const sdk=o.configured?'Connected':'Not configured',quality=String(i.quality||'Checking…').replaceAll('_',' '),rows=Number(f.totalTrainingRows||0),deep=(m.deepArchitecture||[]).length?(m.deepArchitecture||[]).join(' → '):'Waiting for training';
    const brain=state.control?.brain||{},brainMode=String(brain.reasoningMode||'').startsWith('OPENAI_')?'LLM reasoning active':'LLM not configured',unread=Number(brain.unreadCount||0);
    grid.innerHTML=`<article><small>OpenAI API</small><b>${esc(sdk)}${o.model?` · ${esc(o.model)}`:''}</b></article><article><small>Conversation brain</small><b>${esc(brainMode)} · ${brain.contextAwareConversation===false?'basic':'context aware'}</b></article><article><small>Causal reasoning</small><b>${brain.causalReasoning===false?'Off':'On'}</b></article><article><small>Math & probability</small><b>${brain.deterministicMath===false?'Off':'Verified solver on'}</b></article><article><small>Predictive compose</small><b>${brain.predictiveCompose?'On':'Needs OpenAI connection'}</b></article><article><small>Proactive advisor</small><b>${brain.proactiveAdvice===false?'Needs LLM connection':`On · ${unread} unread`}</b></article><article><small>Task execution</small><b>${brain.taskExecution===false?'Off':'Permission-aware tools on'}</b></article><article><small>Visible work trace</small><b>${brain.visibleUiActivity===false?'Off':'On-screen activity on'}</b></article><article><small>Learning state</small><b>${esc(quality)}</b></article><article><small>Training rows</small><b>${num(rows,0)} total · ${num((f.liveCodingRows||0)+(f.liveRecoveryRows||0),0)} live</b></article><article><small>Deep model</small><b>${esc(deep)}</b></article>`;
    if($('intelligenceUpdatedAt'))$('intelligenceUpdatedAt').textContent=i.updatedAt?`Last refreshed ${new Date(i.updatedAt).toLocaleString()}`:'Not trained yet';
    if($('intelligenceBoundary'))$('intelligenceBoundary').textContent=o.configured?'Jivan is connected through a Supabase Edge Function. Role-aware navigation and voice are active; stored high-impact changes remain subject to explicit tools, permissions and human approval controls.':'Jivan is installed but needs OPENAI_API_KEY in Supabase Edge Function Secrets.';
  }
  async function retrainIntelligenceModels(){
    if(STANDALONE_MODE)return toast('Adaptive learning is not included in this direct-Supabase edition.');
    try{const b=$('settingsRetrainIntelligence');if(b)b.disabled=true;const r=await apiFetch('/api/intelligence/train',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({actor_id:controlActorId(),reason:'manual-settings-refresh'})}),out=await r.json();if(!r.ok)throw new Error(out.error||'Could not refresh intelligence models.');state.intelligence=out;renderIntelligenceSettings();toast('Adaptive learning models refreshed.');}catch(err){toast(err.message);}finally{const u=controlUser(),can=Boolean(u&&(u.canManageSettings||u.role==='Administrator'));if($('settingsRetrainIntelligence'))$('settingsRetrainIntelligence').disabled=!can;}
  }

  /* Assurance Regent v6.3.30 — compact Settings modal + persistent theme. */
  const APP_THEME_KEY='assurance-regent-appearance-v1';
  let settingsActivePage='general';
  const SETTINGS_PAGE_META={
    general:['General','Core company display and operational preferences.'],
    appearance:['Appearance','Choose the visual appearance used across Assurance Regent.'],
    costing:['Costing','Operational currency and hourly costing configuration.'],
    access:['Access & Roles','Company authority, approvals and service controls.'],
    intelligence:['AI & Intelligence','Advisory intelligence, reasoning and adaptive learning status.'],
    data:['Data Controls','Developer-only governed database and pipeline workspace.'],
    storage:['Storage','Your uploaded files and personal storage footprint.']
  };
  function normalizeAppTheme(value){return String(value||'').toLowerCase()==='dark'?'dark':'light';}
  function applyAppTheme(value,persist=true){
    const theme=normalizeAppTheme(value);document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;
    if(persist)localSet(APP_THEME_KEY,theme);
    document.querySelectorAll('[data-theme-choice]').forEach(b=>b.classList.toggle('active',b.dataset.themeChoice===theme));
    window.dispatchEvent(new CustomEvent('assurance-regent-theme-change',{detail:{theme}}));return theme;
  }
  function initialAppTheme(){const saved=localGet(APP_THEME_KEY);if(saved)return normalizeAppTheme(saved);try{return matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';}catch{return 'light';}}
  applyAppTheme(initialAppTheme(),false);
  function showSettingsPage(page='general'){
    settingsActivePage=SETTINGS_PAGE_META[page]?page:'general';
    document.querySelectorAll('#controlPaneSettings [data-settings-page]').forEach(x=>{const active=x.dataset.settingsPage===settingsActivePage;x.hidden=!active;});
    document.querySelectorAll('#settingsModalMenu [data-settings-nav]').forEach(b=>b.classList.toggle('active',b.dataset.settingsNav===settingsActivePage));
    const meta=SETTINGS_PAGE_META[settingsActivePage]||SETTINGS_PAGE_META.general;if($('settingsPageTitle'))$('settingsPageTitle').textContent=meta[0];if($('settingsPageSubtitle'))$('settingsPageSubtitle').textContent=meta[1];
    applyAppTheme(document.documentElement.dataset.theme||initialAppTheme(),false);
  }
  function syncSettingsModalPermissions(){
    const ai=$('settingsIntelligenceSection'),aiNav=document.querySelector('[data-settings-nav="intelligence"]');if(aiNav)aiNav.hidden=Boolean(ai?.dataset.permissionHidden==='true');
  }
  function bindSettingsModalUi(){
    const pane=$('controlPaneSettings');if(!pane||pane.dataset.settingsBound==='true')return;pane.dataset.settingsBound='true';
    $('settingsModalClose')?.addEventListener('click',closeControlDrawer);
    $('settingsModalMenu')?.addEventListener('click',e=>{const b=e.target.closest('[data-settings-nav]');if(!b||b.hidden)return;showSettingsPage(b.dataset.settingsNav);});
    $('settingsSearch')?.addEventListener('input',e=>{const q=String(e.target.value||'').trim().toLowerCase();document.querySelectorAll('#settingsModalMenu [data-settings-nav]').forEach(b=>{if(b.dataset.permissionHidden==='true')return;b.hidden=Boolean(q&&!b.textContent.toLowerCase().includes(q));});});
    pane.addEventListener('click',e=>{const b=e.target.closest('[data-theme-choice]');if(!b)return;applyAppTheme(b.dataset.themeChoice,true);toast('Appearance changed to '+b.dataset.themeChoice+' mode.');});
  }


  /* Assurance Regent v6.3.32 — semantic Access & Roles segmentation. */
  const ACCESS_ZONE_INFO={
    people:['People & accounts','Create, select and manage individual user access.'],
    authority:['Roles & authority','Assign functional roles and management authority.'],
    company:['Company controls','Manage company access, service state and directory controls.'],
    approval:['Approvals & controls','Review or apply controlled access and approval changes.']
  };
  function accessZoneKind(text='',index=0){
    const t=String(text||'').toLowerCase();
    if(/billing|subscription|service|offline|payment|monthly amount|directory/.test(t))return 'company';
    if(/approval|approve|review|request|control/.test(t))return 'approval';
    if(/role|authority|permission|developer|administrator|chief executive|ceo|manager|supervisor/.test(t))return 'authority';
    if(/user|employee|account|email|invite|person|staff/.test(t))return 'people';
    return ['people','authority','approval','company'][Math.abs(Number(index)||0)%4];
  }
  function ensureAccessZoneLabel(node,kind){
    if(!node||node.querySelector(':scope > .access-zone-label'))return;
    const info=ACCESS_ZONE_INFO[kind]||ACCESS_ZONE_INFO.people,head=document.createElement('div'),dot=document.createElement('span'),copy=document.createElement('div'),title=document.createElement('b'),desc=document.createElement('small');
    head.className='access-zone-label';dot.className='access-zone-dot';title.textContent=info[0];desc.textContent=info[1];copy.append(title,desc);head.append(dot,copy);node.prepend(head);
  }
  function accessActionKind(label=''){
    const t=String(label||'').toLowerCase();
    if(/delete|remove|revoke|disable|terminate|unlink/.test(t))return 'danger';
    if(/reject|suspend|pause|block|offline/.test(t))return 'warning';
    if(/approve|enable|restore|add|create|invite|activate/.test(t))return 'positive';
    if(/save|apply|update|assign|grant|set|change/.test(t))return 'primary';
    return 'neutral';
  }
  function clarifyAccessButton(button){
    if(!button||button.dataset.accessClarified==='true')return;button.dataset.accessClarified='true';
    const original=String(button.textContent||'').trim(),key=original.toLowerCase(),companyContext=Boolean(button.closest('.company-create-box,.developer-company-directory'));
    const exact={save:'Save access',apply:'Apply role',update:'Update access',approve:'Approve access',reject:'Reject request',remove:'Remove access',delete:'Delete account',disable:'Disable access',enable:'Enable access',restore:'Restore access',edit:'Edit access',open:'Open details'};
    let label=exact[key]||original;
    if(key==='add')label=companyContext?'Add company':'Add user';
    if(key==='create')label=companyContext?'Create company':'Create account';
    if(button.childElementCount===0&&label&&label!==original)button.textContent=label;
    const kind=accessActionKind(label||original),notes={primary:'Applies the selected role or access change.',positive:'Adds, approves or restores access.',warning:'Places access or service into a restricted state.',danger:'Removes or disables access. Review before continuing.',neutral:'Opens or edits the selected access record.'};
    button.classList.add('access-action-button','access-action-'+kind);button.title=notes[kind]||notes.neutral;
    if(!button.getAttribute('aria-label'))button.setAttribute('aria-label',(label||original)+'. '+(notes[kind]||notes.neutral));
  }
  function ensureAccessLegend(section){
    if(!section||section.querySelector('.access-zone-legend'))return;
    const legend=document.createElement('div');legend.className='access-zone-legend';
    [['people','User access'],['authority','Roles'],['approval','Approvals']].forEach(entry=>{const chip=document.createElement('span'),dot=document.createElement('i');chip.className=entry[0];chip.append(dot,document.createTextNode(entry[1]));legend.append(chip);});
    const head=section.querySelector('.settings-section-head');if(head)head.insertAdjacentElement('afterend',legend);else section.prepend(legend);
  }
  function decorateAccessRolesUi(){
    const section=$('accessManagementSection');if(!section)return;
    const longNote=section.querySelector('.department-authority-note');if(longNote)longNote.remove();
    const headCopy=section.querySelector('.settings-section-head small');if(headCopy)headCopy.textContent='Manage user access, functional roles and approvals.';
    ensureAccessLegend(section);
    const grid=section.querySelector('.access-admin-grid');if(grid)[...grid.children].forEach((card,index)=>{if(!card.matches('article,section,div,form'))return;const kind=accessZoneKind(card.textContent,index);card.classList.remove('access-zone-people','access-zone-authority','access-zone-company','access-zone-approval');card.classList.add('access-zone-card','access-zone-'+kind);ensureAccessZoneLabel(card,kind);});
    const companyBox=section.querySelector('.company-create-box');if(companyBox){companyBox.classList.add('access-zone-card','access-zone-company');ensureAccessZoneLabel(companyBox,'company');}
    const directory=section.querySelector('.developer-company-directory');if(directory){directory.classList.add('access-zone-card','access-zone-company');ensureAccessZoneLabel(directory,'company');}
    section.querySelectorAll('button').forEach(clarifyAccessButton);
  }


  /* Assurance Regent v6.3.33 — Developer Data Controls + personal Storage. */
  let dataControlsCatalog=null,dataControlsAccounts=[],dataControlsPipeline='',dataControlsTable='',dataControlsOffset=0,dataControlsPageSize=40,dataControlsCurrent=null,dataEditorContext=null;
  const DATA_READ_RPCS=['assurance_regent_browser_data_controls_catalog','assurance_regent_browser_data_controls_rows','assurance_regent_browser_data_controls_accounts','assurance_regent_browser_storage_summary'];
  function dataDeveloperAllowed(){return functionalAuthority(effectiveUserOrg(controlUser()||{}))==='DEVELOPER';}
  function humanBytes(value){const n=Math.max(0,Number(value||0)),u=['B','KB','MB','GB','TB'];let i=0,x=n;while(x>=1024&&i<u.length-1){x/=1024;i++;}return (i?x.toFixed(x>=10?1:2):Math.round(x))+' '+u[i];}
  function dataCellText(value){if(value===null||value===undefined)return '—';if(typeof value==='object'){try{return JSON.stringify(value);}catch{return String(value);}}return String(value);}
  function keyForDataRow(row,primary){const out={};(primary||[]).forEach(k=>out[k]=row?.[k]);return out;}
  function setDataWorkspaceMode(mode){const w=$('developerDataWorkspace'),open=$('dataWorkspaceOpen');if(!w)return;w.classList.toggle('minimized',mode==='minimized');w.classList.toggle('maximized',mode==='maximized');w.classList.toggle('closed',mode==='closed');document.body.classList.toggle('data-workspace-maximized',mode==='maximized');if(open)open.hidden=mode!=='closed';}
  function renderDataPipelineNav(){const box=$('dataPipelineNav');if(!box||!dataControlsCatalog)return;const pipes=Array.isArray(dataControlsCatalog.pipelines)?dataControlsCatalog.pipelines:[];if(!dataControlsPipeline&&pipes.length)dataControlsPipeline=pipes[0].name;box.innerHTML='<b>Pipelines</b>'+pipes.map(p=>'<button type="button" data-pipeline="'+esc(p.name)+'" class="'+(p.name===dataControlsPipeline?'active':'')+'">'+esc(p.name)+'<span>'+Number(p.tables||0)+'</span></button>').join('');renderDataTableTabs();}
  function renderDataTableTabs(){const box=$('dataTableTabs');if(!box||!dataControlsCatalog)return;const tables=(dataControlsCatalog.tables||[]).filter(t=>t.pipeline===dataControlsPipeline),special=dataControlsPipeline==='Identity & Access'?[{table:'__accounts__',label:'Account maintenance',writable:true},{table:'__companies__',label:'Company controls',writable:true}]:[];const all=special.concat(tables);if(!all.some(t=>t.table===dataControlsTable))dataControlsTable=all[0]?.table||'';box.innerHTML=all.map(t=>'<button type="button" data-data-table="'+esc(t.table)+'" class="'+(t.table===dataControlsTable?'active':'')+'">'+esc(t.label||t.table)+(t.writable?' · Edit':'')+'</button>').join('');if(dataControlsTable)loadDataControlsTable(dataControlsTable,true);else $('dataConsoleTableWrap').innerHTML='<div class="storage-empty">No tables are available in this pipeline.</div>';}
  async function loadDataControlsCatalog(force=false){if(!dataDeveloperAllowed())return;try{if(!dataControlsCatalog||force)dataControlsCatalog=await supabaseRpc('assurance_regent_browser_data_controls_catalog',{p_token:browserSessionToken},{bypassCache:true});dataControlsAccounts=(await supabaseRpc('assurance_regent_browser_data_controls_accounts',{p_token:browserSessionToken},{bypassCache:true}))?.accounts||[];if($('dataPipelineCount'))$('dataPipelineCount').textContent=Number(dataControlsCatalog?.pipeline_count||0);if($('dataTableCount'))$('dataTableCount').textContent=Number(dataControlsCatalog?.table_count||0);if($('dataAccountCount'))$('dataAccountCount').textContent=dataControlsAccounts.length;renderDataPipelineNav();}catch(err){if($('dataConsoleTableWrap'))$('dataConsoleTableWrap').innerHTML='<div class="storage-empty">'+esc(err.message||'Could not load Data Controls.')+'</div>';}}
  function renderAccountMaintenance(){const rows=dataControlsAccounts||[],cols=['role','companyId','position','department','approvalStatus','active'];const head='<table class="data-console-table account-maintenance-table"><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Password / Security</th>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'<th>Actions</th></tr></thead><tbody>';const body=rows.map(a=>{const secured=passwordStateLabel(a),updated=a.password_updated_at?String(a.password_updated_at).slice(0,10):'';return '<tr><td>'+esc(dataCellText(a.name))+'</td><td>'+esc(dataCellText(a.username))+'</td><td>'+esc(dataCellText(a.email))+'</td><td class="password-security-cell"><span class="password-security-state '+(secured==='Secured'?'secured':'unset')+'">'+secured+'</span>'+(updated?'<small>Updated '+esc(updated)+'</small>':'')+'<button type="button" data-account-password="'+esc(a.id)+'">'+(a.password_reset_available?'Reset password':'Set password')+'</button></td>'+cols.map(c=>'<td>'+esc(dataCellText(a[c]))+'</td>').join('')+'<td><div class="data-account-actions"><button type="button" data-account-edit="'+esc(a.id)+'">Edit</button>'+(a.active===false?'<button type="button" class="activate" data-account-action="ACTIVATE" data-account-id="'+esc(a.id)+'">Activate</button>':'<button type="button" class="suspend" data-account-action="SUSPEND" data-account-id="'+esc(a.id)+'">Suspend</button>')+'<button type="button" class="delete" data-account-delete="'+esc(a.id)+'">Delete</button></div></td></tr>';}).join('');$('dataConsoleTableWrap').innerHTML=head+(body||'<tr><td colspan="11">No accounts found.</td></tr>')+'</tbody></table>';if($('dataWorkspaceTitle'))$('dataWorkspaceTitle').textContent='Account maintenance';if($('dataWorkspaceSubtitle'))$('dataWorkspaceSubtitle').textContent='Passwords remain encrypted; use Set/Reset password to replace credentials securely.';if($('dataConsoleStatus'))$('dataConsoleStatus').textContent=rows.length+' accounts';}
  function renderDataRows(payload){dataControlsCurrent=payload;const rows=payload?.rows||[],cols=payload?.columns||[],editable=new Set(payload?.editable_columns||[]),pk=payload?.primary_key||[];let html='<table class="data-console-table"><thead><tr>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+(payload?.writable?'<th>Actions</th>':'')+'</tr></thead><tbody>';html+=rows.map((r,i)=>'<tr>'+cols.map(c=>{const v=r[c],json=v&&typeof v==='object';return '<td class="'+(json?'json-cell':'')+'" title="'+esc(dataCellText(v)).replace(/"/g,'&quot;')+'">'+esc(dataCellText(v))+'</td>';}).join('')+(payload?.writable?'<td><div class="data-account-actions"><button type="button" data-row-edit="'+i+'">Edit</button></div></td>':'')+'</tr>').join('');html+=(rows.length?'':'<tr><td colspan="'+Math.max(1,cols.length+1)+'">No records in this table.</td></tr>')+'</tbody></table>';$('dataConsoleTableWrap').innerHTML=html;if($('dataWorkspaceTitle'))$('dataWorkspaceTitle').textContent=payload?.label||payload?.table||'Data table';if($('dataWorkspaceSubtitle'))$('dataWorkspaceSubtitle').textContent=(payload?.pipeline||'')+' · '+(payload?.writable?'Controlled editing enabled':'Read-only');if($('dataConsoleStatus'))$('dataConsoleStatus').textContent='Rows '+(Number(payload?.offset||0)+1)+'–'+Math.min(Number(payload?.total||0),Number(payload?.offset||0)+rows.length)+' of '+Number(payload?.total||0);if($('dataPrevPage'))$('dataPrevPage').disabled=Number(payload?.offset||0)<=0;if($('dataNextPage'))$('dataNextPage').disabled=Number(payload?.offset||0)+Number(payload?.limit||40)>=Number(payload?.total||0);}
  async function loadDataControlsTable(table=dataControlsTable,reset=false){if(!dataDeveloperAllowed()||!table)return;if(reset)dataControlsOffset=0;dataControlsTable=table;document.querySelectorAll('[data-data-table]').forEach(b=>b.classList.toggle('active',b.dataset.dataTable===table));if(table==='__accounts__'){renderAccountMaintenance();return;}if(table==='__companies__'){renderDataCompanyControls();return;}if($('dataConsoleTableWrap'))$('dataConsoleTableWrap').innerHTML='<div class="storage-empty">Loading '+esc(table)+'…</div>';try{const out=await supabaseRpc('assurance_regent_browser_data_controls_rows',{p_token:browserSessionToken,p_table:table,p_limit:dataControlsPageSize,p_offset:dataControlsOffset},{bypassCache:true});renderDataRows(out);}catch(err){$('dataConsoleTableWrap').innerHTML='<div class="storage-empty">'+esc(err.message||'Could not load table.')+'</div>';}}
  function openDataRowEditor(row,index){const current=dataControlsCurrent;if(!current||!row)return;const editable=current.editable_columns||[];dataEditorContext={table:current.table,key:keyForDataRow(row,current.primary_key||[]),row,index,fields:editable};$('dataRowEditorTitle').textContent='Edit '+(current.label||current.table);$('dataRowEditorFields').innerHTML=editable.map(c=>{const v=row[c],json=v&&typeof v==='object',text=json?JSON.stringify(v,null,2):dataCellText(v)==='—'?'':String(v??'');return '<label>'+esc(c)+(json?'<textarea data-edit-column="'+esc(c)+'" data-json="true">'+esc(text)+'</textarea>':'<input data-edit-column="'+esc(c)+'" value="'+esc(text).replace(/"/g,'&quot;')+'" />')+'</label>';}).join('')||'<div class="storage-empty">This table is read-only.</div>';$('dataRowEditor').hidden=false;}
  async function saveDataRowEditor(){if(!dataEditorContext)return;if(dataEditorContext.type==='password'){const p=$('dataRowEditorFields')?.querySelector('[data-password-new]')?.value||'',c=$('dataRowEditorFields')?.querySelector('[data-password-confirm]')?.value||'';if(p.length<8)return toast('Password must contain at least 8 characters.');if(p!==c)return toast('The password confirmation does not match.');try{$('dataRowEditorSave').disabled=true;await supabaseRpc('assurance_regent_browser_admin_set_password',{p_token:browserSessionToken,p_user_id:dataEditorContext.userId,p_new_password:p});$('dataRowEditor').hidden=true;toast('Password replaced securely. Existing sessions for that user were revoked where applicable.');await loadDataControlsCatalog(true);dataControlsTable='__accounts__';renderAccountMaintenance();}catch(err){toast(err.message);}finally{$('dataRowEditorSave').disabled=false;}return;}const patch={};for(const el of document.querySelectorAll('#dataRowEditorFields [data-edit-column]')){let value=el.value;if(el.dataset.json==='true'){try{value=value.trim()?JSON.parse(value):null;}catch{return toast('Fix the JSON value in '+el.dataset.editColumn+'.');}}patch[el.dataset.editColumn]=value===''?null:value;}try{$('dataRowEditorSave').disabled=true;await supabaseRpc('assurance_regent_browser_data_controls_update',{p_token:browserSessionToken,p_table:dataEditorContext.table,p_key:dataEditorContext.key,p_patch:patch});$('dataRowEditor').hidden=true;toast('Database record updated and audited.');await loadDataControlsTable(dataEditorContext.table,false);}catch(err){toast(err.message);}finally{$('dataRowEditorSave').disabled=false;}}
  async function accountStatusAction(id,action){if(!id)return;const verb=action==='SUSPEND'?'suspend':'activate';if(!confirm('Confirm '+verb+' for account '+id+'?'))return;try{await supabaseRpc('assurance_regent_browser_admin_account_status',{p_token:browserSessionToken,p_user_id:id,p_action:action,p_reason:'Developer Data Controls'});toast('Account '+verb+' action completed.');await loadDataControlsCatalog(true);dataControlsTable='__accounts__';renderAccountMaintenance();}catch(err){toast(err.message);}}
