  function openAccountEditor(id){const a=(dataControlsAccounts||[]).find(x=>String(x.id)===String(id));if(!a)return;const role=prompt('System role (Developer, Administrator, Employee):',a.role||'Employee');if(role===null)return;const company=role==='Developer'?'':prompt('Company ID:',a.companyId||'');if(company===null)return;const position=prompt('Position:',a.position||'');if(position===null)return;const department=prompt('Department:',a.department||'');if(department===null)return;const supervisor=String(a.supervisor||'');const supervisoryRole=prompt('Supervisory / functional authority:',a.supervisoryRole||'');if(supervisoryRole===null)return;supabaseRpc('assurance_regent_browser_admin_update_user',{p_token:browserSessionToken,p_user_id:id,p_role:role,p_company_id:company,p_position:position,p_department:department,p_supervisor:supervisor,p_supervisory_role:supervisoryRole}).then(async()=>{toast('Account authority updated.');await loadDataControlsCatalog(true);dataControlsTable='__accounts__';renderAccountMaintenance();}).catch(err=>toast(err.message));}
  async function loadPersonalStorage(){if(!browserSessionToken)return;const host=$('storageRecentFiles');try{const out=await supabaseRpc('assurance_regent_browser_storage_summary',{p_token:browserSessionToken},{bypassCache:true}),total=Number(out?.total_bytes||0),count=Number(out?.file_count||0),quota=Number(out?.quota_bytes||0),quotaPct=quota>0?Number(out?.quota_percent||0):100;if($('storageHeadline'))$('storageHeadline').textContent=humanBytes(total)+(quota>0?' of '+humanBytes(quota):' uploaded');if($('storageSubtitle'))$('storageSubtitle').textContent=count+' file'+(count===1?'':'s')+(quota>0?' · '+quotaPct.toFixed(1)+'% of your configured allowance':' · click a category to manage its files');if($('storageTotalProgress'))$('storageTotalProgress').style.width=(total<=0?0:Math.max(2,Math.min(100,quota>0?quotaPct:100)))+'%';const cats=Array.isArray(out?.categories)?out.categories:[];$('storageBreakdown').innerHTML=cats.map(c=>'<button type="button" class="storage-category-card" data-storage-category="'+esc(c.key||'all')+'"><div class="storage-breakdown-head"><b>'+esc(c.label)+'</b><span>'+humanBytes(c.bytes)+' · '+Number(c.files||0)+' files <i>›</i></span></div><div class="storage-progress"><i style="width:'+Math.max(0,Math.min(100,Number(c.percent||0)))+'%"></i></div></button>').join('')||'<div class="storage-empty">No uploaded files yet.</div>';const recent=Array.isArray(out?.recent_files)?out.recent_files:[];host.innerHTML=recent.map(f=>'<div class="storage-file-row"><button type="button" data-storage-open="'+esc(f.id)+'" data-storage-name="'+esc(f.name||'file')+'">'+esc(f.name||'file')+'</button><span>'+humanBytes(f.size_bytes)+'</span><time>'+esc(String(f.created_at||'').slice(0,10))+'</time></div>').join('')||'<div class="storage-empty">No recent uploads.</div>';}catch(err){if(host)host.innerHTML='<div class="storage-empty">'+esc(err.message||'Could not load storage.')+'</div>';}}

  /* Assurance Regent v6.3.34 — secure password administration + personal Storage library. */
  let storageLibraryKind='all',storageLibraryOffset=0,storageLibraryLimit=40,storageLibraryFiles=[],storageLibraryTotal=0,storageLibrarySelected=new Set(),storageLibrarySearch='';
  function passwordStateLabel(account){return String(account?.password_status||'').toUpperCase()==='SECURED'?'Secured':'Not set';}
  function openPasswordEditor(id){
    const account=(dataControlsAccounts||[]).find(x=>String(x.id)===String(id));if(!account)return;
    dataEditorContext={type:'password',userId:id};
    $('dataRowEditorTitle').textContent=(account.password_reset_available?'Reset':'Set')+' password · '+(account.name||account.username||id);
    $('dataRowEditorFields').innerHTML='<div class="password-security-note">Passwords are never displayed. Enter a new password to replace the stored encrypted credential.</div><label>New password<input type="password" autocomplete="new-password" data-password-new /></label><label>Confirm password<input type="password" autocomplete="new-password" data-password-confirm /></label>';
    $('dataRowEditor').hidden=false;
  }
  function storageKindLabel(kind){return kind==='documents'?'Documents':kind==='images'?'Images':kind==='other'?'Other files':'All files';}
  function renderStorageSelectionState(){
    const selected=storageLibrarySelected.size,deleteBtn=$('storageLibraryDelete'),selectAll=$('storageLibrarySelectAll'),status=$('storageLibraryStatus');
    if(deleteBtn){deleteBtn.disabled=!selected;deleteBtn.textContent=selected?'Delete selected ('+selected+')':'Delete selected';}
    if(selectAll){const visible=storageLibraryFiles.map(f=>String(f.id));selectAll.checked=Boolean(visible.length&&visible.every(id=>storageLibrarySelected.has(id)));selectAll.indeterminate=Boolean(selected&&!selectAll.checked);}
    if(status)status.textContent=selected+' selected · '+storageLibraryTotal+' '+storageKindLabel(storageLibraryKind).toLowerCase();
  }
  function renderStorageLibrary(){
    const host=$('storageLibraryList');if(!host)return;
    host.innerHTML=storageLibraryFiles.map(f=>'<div class="storage-library-row"><label class="storage-file-check"><input type="checkbox" data-storage-select="'+esc(f.id)+'" '+(storageLibrarySelected.has(String(f.id))?'checked':'')+' aria-label="Select '+esc(f.name||'file').replace(/"/g,'&quot;')+'" /></label><button type="button" class="storage-library-file" data-storage-open="'+esc(f.id)+'" data-storage-name="'+esc(f.name||'file')+'"><span class="storage-file-icon">'+(String(f.kind)==='images'?'▧':String(f.kind)==='documents'?'▤':'◇')+'</span><span><b>'+esc(f.name||'file')+'</b><small>'+esc(f.mime_type||'File')+' · '+humanBytes(f.size_bytes)+'</small></span></button><time>'+esc(String(f.created_at||'').slice(0,10))+'</time></div>').join('')||'<div class="storage-empty">No '+storageKindLabel(storageLibraryKind).toLowerCase()+' match this view.</div>';
    if($('storageLibraryPrev'))$('storageLibraryPrev').disabled=storageLibraryOffset<=0;
    if($('storageLibraryNext'))$('storageLibraryNext').disabled=storageLibraryOffset+storageLibraryLimit>=storageLibraryTotal;
    renderStorageSelectionState();
  }
  async function loadStorageLibrary(reset=false){
    if(!browserSessionToken)return;if(reset)storageLibraryOffset=0;
    const host=$('storageLibraryList');if(host)host.innerHTML='<div class="storage-empty">Loading '+storageKindLabel(storageLibraryKind).toLowerCase()+'…</div>';
    try{
      const out=await supabaseRpc('assurance_regent_browser_storage_library',{p_token:browserSessionToken,p_kind:storageLibraryKind,p_search:storageLibrarySearch,p_limit:storageLibraryLimit,p_offset:storageLibraryOffset},{bypassCache:true});
      storageLibraryFiles=Array.isArray(out?.files)?out.files:[];storageLibraryTotal=Number(out?.total||0);renderStorageLibrary();
    }catch(err){if(host)host.innerHTML='<div class="storage-empty">'+esc(err.message||'Could not load your file library.')+'</div>';}
  }
  function openStorageLibrary(kind='all'){
    storageLibraryKind=['documents','images','other'].includes(kind)?kind:'all';storageLibrarySelected.clear();storageLibrarySearch='';storageLibraryOffset=0;
    const panel=$('storageLibraryPanel');if(panel)panel.hidden=false;if($('storageLibrarySearch'))$('storageLibrarySearch').value='';
    document.querySelectorAll('#storageLibraryFilter [data-storage-kind]').forEach(b=>b.classList.toggle('active',b.dataset.storageKind===storageLibraryKind));
    loadStorageLibrary(true);
  }
  function closeStorageLibrary(){if($('storageLibraryPanel'))$('storageLibraryPanel').hidden=true;storageLibrarySelected.clear();renderStorageSelectionState();}
  async function deleteSelectedStorage(){
    const ids=[...storageLibrarySelected];if(!ids.length)return;if(!confirm('Delete '+ids.length+' selected file'+(ids.length===1?'':'s')+' from your storage? This cannot be undone.'))return;
    const btn=$('storageLibraryDelete');try{if(btn)btn.disabled=true;const out=await supabaseFunction('assurance-regent-files',{mode:'delete_many',file_ids:ids});storageLibrarySelected.clear();toast(Number(out?.deleted||ids.length)+' file'+(Number(out?.deleted||ids.length)===1?'':'s')+' deleted.');await loadPersonalStorage();await loadStorageLibrary(false);}catch(err){toast(err.message);}finally{renderStorageSelectionState();}
  }


  /* Assurance Regent v6.3.35 — compact Developer Company Controls. */
  let dataCompanyPage=1,dataCompanyPageSize=5,dataCompanyOpenId='',dataCompanyCreateOpen=false;
  function dataCompanyRows(){return Array.isArray(state.control?.profile?.companies)?state.control.profile.companies:[];}
  function dataCompanyAccounts(companyId){return (dataControlsAccounts||[]).filter(x=>String(x.companyId||'')===String(companyId||''));}
