  function dataCompanyWorkforceCount(companyId){const employees=dataCompanyEmployees(companyId),accounts=dataCompanyAccounts(companyId).filter(x=>x.role!=='Developer'&&x.active!==false);return employees.length||accounts.length;}
  function dataCompanyWorkforceBand(count){const n=Math.max(0,Number(count||0));if(!n)return 'Workforce not recorded';if(n<=10)return 'Workforce 1–10';if(n<=20)return 'Workforce 11–20';if(n<=50)return 'Workforce 21–50';if(n<=100)return 'Workforce 51–100';if(n<=250)return 'Workforce 101–250';if(n<=500)return 'Workforce 251–500';return 'Workforce 501+';}
  function dataCompanyContact(company){const id=company?.id||'',accounts=dataCompanyAccounts(id),employees=dataCompanyEmployees(id),leaderAccount=accounts.find(x=>/chief executive|ceo|country director|managing director/i.test(String(x.position||x.supervisoryRole||'')))||accounts.find(x=>x.role==='Administrator')||accounts[0],leaderEmployee=employees.find(x=>/chief executive|ceo|country director|managing director/i.test(String(x.position||'')))||employees[0];return {email:company?.contactEmail||company?.email||leaderAccount?.email||leaderEmployee?.email||'',phone:company?.contactPhone||company?.phone||leaderEmployee?.phone||''};}
  function dataCompanyLogo(company){const id=String(company?.id||''),vacancy=(engine.state.vacancies||[]).find(v=>String(v.companyId||'')===id&&(v.companyLogo||v.logo));return safeProfilePhoto(company?.logo||company?.companyLogo||company?.profilePhoto||vacancy?.companyLogo||vacancy?.logo||'')||'';}
