  function renderDataCompanyControls(){if(!dataDeveloperAllowed())return;bindDataCompanyControlsUi();const host=$('dataConsoleTableWrap');if(!host)return;const companies=dataCompanyRows(),pages=Math.max(1,Math.ceil(companies.length/dataCompanyPageSize));dataCompanyPage=Math.max(1,Math.min(pages,dataCompanyPage));const start=(dataCompanyPage-1)*dataCompanyPageSize,rows=companies.slice(start,start+dataCompanyPageSize);let html='<div class="company-controls-shell"><div class="company-controls-toolbar"><div><b>Company Controls</b><small>Developer-only service directory · maximum five companies per page</small></div><button type="button" class="btn secondary small" data-company-create-toggle>'+(dataCompanyCreateOpen?'Hide new company':'New company')+'</button></div>'+dataCompanyCreateMarkup()+'<div class="company-control-grid">';html+=rows.map(c=>{const enabled=c.systemEnabled!==false,contact=dataCompanyContact(c),logo=dataCompanyLogo(c),band=dataCompanyWorkforceBand(dataCompanyWorkforceCount(c.id));return '<article class="company-control-card '+(enabled?'online':'offline')+'" data-company-control-card="'+esc(c.id)+'"><div class="company-control-logo">'+(logo?'<img src="'+esc(logo)+'" alt="'+esc(c.name||'Company')+' logo" />':esc(dataCompanyInitials(c)))+'</div><div class="company-control-identity"><b>'+esc(c.name||c.code||c.id)+'</b><small>Company ID · '+esc(c.id)+'</small><span class="company-workforce-band">'+esc(band)+'</span><button type="button" class="company-delete-button" data-company-delete="'+esc(c.id)+'">Delete</button></div><div class="company-control-contact"><span>'+esc(contact.phone||'Contact number not set')+'</span><small>'+esc(contact.email||'Email not set')+'</small></div><label class="company-service-toggle" title="Switch company service on or off"><input type="checkbox" data-company-switch="'+esc(c.id)+'" '+(enabled?'checked':'')+'/><i></i><em>'+(enabled?'On':'Off')+'</em></label><button type="button" class="company-control-open" data-company-open="'+esc(c.id)+'">Open</button></article>';}).join('');html+=(rows.length?'':'<div class="storage-empty">No companies configured yet.</div>')+'</div>'+dataCompanyPagination(pages);const opened=companies.find(c=>String(c.id)===String(dataCompanyOpenId));html+=dataCompanyDetailMarkup(opened)+'</div>';host.innerHTML=html;if($('dataWorkspaceTitle'))$('dataWorkspaceTitle').textContent='Company Controls';if($('dataWorkspaceSubtitle'))$('dataWorkspaceSubtitle').textContent='Company-level service governance without employee names or exact user counts.';if($('dataConsoleStatus'))$('dataConsoleStatus').textContent=companies.length+' companies · page '+dataCompanyPage+' of '+pages;if($('dataPrevPage'))$('dataPrevPage').disabled=true;if($('dataNextPage'))$('dataNextPage').disabled=true;}
