  function bindDataControlsStorageUi(){const pane=$('controlPaneSettings');if(!pane||pane.dataset.dataStorageBound==='true')return;pane.dataset.dataStorageBound='true';$('dataPipelineNav')?.addEventListener('click',e=>{const b=e.target.closest('[data-pipeline]');if(!b)return;dataControlsPipeline=b.dataset.pipeline;dataControlsOffset=0;renderDataPipelineNav();});$('dataTableTabs')?.addEventListener('click',e=>{const b=e.target.closest('[data-data-table]');if(!b)return;loadDataControlsTable(b.dataset.dataTable,true);});$('dataTableRefresh')?.addEventListener('click',()=>dataControlsTable==='__accounts__'?loadDataControlsCatalog(true):loadDataControlsTable(dataControlsTable,false));$('dataPrevPage')?.addEventListener('click',()=>{dataControlsOffset=Math.max(0,dataControlsOffset-dataControlsPageSize);loadDataControlsTable(dataControlsTable,false);});$('dataNextPage')?.addEventListener('click',()=>{dataControlsOffset+=dataControlsPageSize;loadDataControlsTable(dataControlsTable,false);});$('dataWorkspaceMinimize')?.addEventListener('click',()=>setDataWorkspaceMode($('developerDataWorkspace')?.classList.contains('minimized')?'normal':'minimized'));$('dataWorkspaceMaximize')?.addEventListener('click',()=>setDataWorkspaceMode($('developerDataWorkspace')?.classList.contains('maximized')?'normal':'maximized'));$('dataWorkspaceClose')?.addEventListener('click',()=>setDataWorkspaceMode('closed'));$('dataWorkspaceOpen')?.addEventListener('click',()=>setDataWorkspaceMode('normal'));$('dataConsoleTableWrap')?.addEventListener('click',e=>{const edit=e.target.closest('[data-row-edit]');if(edit&&dataControlsCurrent)return openDataRowEditor(dataControlsCurrent.rows[Number(edit.dataset.rowEdit)],Number(edit.dataset.rowEdit));const status=e.target.closest('[data-account-action]');if(status)return accountStatusAction(status.dataset.accountId,status.dataset.accountAction);const del=e.target.closest('[data-account-delete]');if(del)return deleteAccountFromDataControls(del.dataset.accountDelete);const password=e.target.closest('[data-account-password]');if(password)return openPasswordEditor(password.dataset.accountPassword);const accountEdit=e.target.closest('[data-account-edit]');if(accountEdit)return openAccountEditor(accountEdit.dataset.accountEdit);});$('dataRowEditorClose')?.addEventListener('click',()=>{$('dataRowEditor').hidden=true;});$('dataRowEditorCancel')?.addEventListener('click',()=>{$('dataRowEditor').hidden=true;});$('dataRowEditorSave')?.addEventListener('click',saveDataRowEditor);$('storageRefresh')?.addEventListener('click',()=>{loadPersonalStorage();if(!$('storageLibraryPanel')?.hidden)loadStorageLibrary(false);});$('storageRecentFiles')?.addEventListener('click',e=>{const b=e.target.closest('[data-storage-open]');if(b)openPersistentFile(b.dataset.storageOpen,b.dataset.storageName).catch(err=>toast(err.message));});$('storageBreakdown')?.addEventListener('click',e=>{const b=e.target.closest('[data-storage-category]');if(b)openStorageLibrary(b.dataset.storageCategory);});$('storageManageFiles')?.addEventListener('click',()=>openStorageLibrary('all'));$('storageLibraryClose')?.addEventListener('click',closeStorageLibrary);$('storageLibraryFilter')?.addEventListener('click',e=>{const b=e.target.closest('[data-storage-kind]');if(!b)return;storageLibraryKind=b.dataset.storageKind;storageLibrarySelected.clear();document.querySelectorAll('#storageLibraryFilter [data-storage-kind]').forEach(x=>x.classList.toggle('active',x===b));loadStorageLibrary(true);});let searchTimer=null;$('storageLibrarySearch')?.addEventListener('input',e=>{storageLibrarySearch=String(e.target.value||'').trim();clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadStorageLibrary(true),220);});$('storageLibrarySelectAll')?.addEventListener('change',e=>{storageLibraryFiles.forEach(f=>{const id=String(f.id);if(e.target.checked)storageLibrarySelected.add(id);else storageLibrarySelected.delete(id);});renderStorageLibrary();});$('storageLibraryList')?.addEventListener('change',e=>{const c=e.target.closest('[data-storage-select]');if(!c)return;const id=String(c.dataset.storageSelect);if(c.checked)storageLibrarySelected.add(id);else storageLibrarySelected.delete(id);renderStorageSelectionState();});$('storageLibraryList')?.addEventListener('click',e=>{const b=e.target.closest('[data-storage-open]');if(b)openPersistentFile(b.dataset.storageOpen,b.dataset.storageName).catch(err=>toast(err.message));});$('storageLibraryDelete')?.addEventListener('click',deleteSelectedStorage);$('storageLibraryPrev')?.addEventListener('click',()=>{storageLibraryOffset=Math.max(0,storageLibraryOffset-storageLibraryLimit);loadStorageLibrary(false);});$('storageLibraryNext')?.addEventListener('click',()=>{storageLibraryOffset+=storageLibraryLimit;loadStorageLibrary(false);});}

  /* Assurance Regent v6.3.37 — personal AI preferences, natural voice handoff, Company Hub and governed company purge. */
  const AI_VOICE_OPTIONS=['alloy','ash','ballad','coral','echo','fable','onyx','nova','sage','shimmer','verse','marin','cedar'];
  let aiPreferencesLoaded=false,companyDirectoryLoading=false,companyDirectoryKey='',companyHubLoading=false,companyPurgePreview=null;
  function agentDisplayText(v=''){return String(v||'').replace(/^\s{0,3}#{1,6}\s*/gm,'').replace(/\*\*([^*]+)\*\*/g,'$1').replace(/__([^_]+)__/g,'$1').replace(/`{1,3}/g,'').replace(/[ \t]+\n/g,'\n').trim();}
  async function synthesizeConnectedVoice(text,agent='JIVAN',voiceOverride='',speedOverride=null){const clean=agentDisplayText(text).slice(0,4096);if(!clean||!browserSessionToken)return null;const r=await managedFetch(`${SUPABASE_URL}/functions/v1/jivan-voice`,{method:'POST',headers:{apikey:SUPABASE_PUBLISHABLE_KEY,'content-type':'application/json'},body:JSON.stringify({session_token:browserSessionToken,text:clean,agent,voice_override:voiceOverride||'',speed_override:speedOverride})},{timeout:95000,retries:0});if(!r.ok){const t=await r.text();let b={};try{b=JSON.parse(t)}catch{}throw new Error(b.error||t||'AI voice unavailable.');}const blob=await r.blob();return {url:URL.createObjectURL(blob),blob};}
  function playVoiceUrl(url){return new Promise((resolve,reject)=>{if(!url)return resolve(false);const a=new Audio(url),finish=(ok,err)=>{try{URL.revokeObjectURL(url)}catch{};ok?resolve(true):reject(err||new Error('Audio playback failed.'));};a.onended=()=>finish(true);a.onerror=()=>finish(false,new Error('Audio playback failed.'));a.play().catch(e=>finish(false,e));});}
  function speakAuthPromptAwait(text=''){return new Promise(resolve=>{try{if(!text||!window.speechSynthesis)return resolve(false);window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text));u.rate=1;u.pitch=1;u.volume=.9;u.onend=()=>resolve(true);u.onerror=()=>resolve(false);window.speechSynthesis.speak(u);}catch{resolve(false);}});}
  async function loadAiPreferences(force=false){if(!browserSessionToken)return null;if(aiPreferencesLoaded&&!force)return state.aiPreferences||null;try{const p=await supabaseRpc('assurance_regent_browser_ai_preferences_get',{p_token:browserSessionToken},{bypassCache:force});state.aiPreferences=p||{};aiPreferencesLoaded=true;const voices=AI_VOICE_OPTIONS.map(v=>`<option value="${esc(v)}">${esc(v[0].toUpperCase()+v.slice(1))}</option>`).join('');if($('aiJivanVoice')){$('aiJivanVoice').innerHTML=voices;$('aiJivanVoice').value=p.jivanVoice||'marin';}if($('aiZariVoice')){$('aiZariVoice').innerHTML=voices;$('aiZariVoice').value=p.zariVoice||'coral';}if($('aiWritingStyle'))$('aiWritingStyle').value=p.writingStyle||'professional';if($('aiResponseLength'))$('aiResponseLength').value=p.responseLength||'balanced';if($('aiVerbosity'))$('aiVerbosity').value=p.verbosity||'medium';if($('aiEmojiLevel'))$('aiEmojiLevel').value=p.emojiLevel||'light';if($('aiTemperature'))$('aiTemperature').value=Number(p.temperature??.7);if($('aiTemperatureValue'))$('aiTemperatureValue').textContent=Number(p.temperature??.7).toFixed(2);if($('aiVoiceSpeed'))$('aiVoiceSpeed').value=Number(p.voiceSpeed||1);if($('aiVoiceSpeedValue'))$('aiVoiceSpeedValue').textContent=Number(p.voiceSpeed||1).toFixed(2)+'×';return p;}catch(err){console.warn('AI preferences unavailable',err);return null;}}
  async function saveAiPreferences(){try{const p=await supabaseRpc('assurance_regent_browser_ai_preferences_set',{p_token:browserSessionToken,p_writing_style:$('aiWritingStyle')?.value||'professional',p_temperature:Number($('aiTemperature')?.value||.7),p_response_length:$('aiResponseLength')?.value||'balanced',p_verbosity:$('aiVerbosity')?.value||'medium',p_jivan_voice:$('aiJivanVoice')?.value||'marin',p_zari_voice:$('aiZariVoice')?.value||'coral',p_voice_speed:Number($('aiVoiceSpeed')?.value||1),p_emoji_level:$('aiEmojiLevel')?.value||'light'},{bypassCache:true});state.aiPreferences=p;aiPreferencesLoaded=true;if($('aiPreferenceStatus'))$('aiPreferenceStatus').textContent='Saved';toast('AI writing and voice preferences saved.');}catch(err){toast(err.message||'Could not save AI preferences.');}}
  async function previewAiVoice(agent){const select=agent==='ZARI'?'aiZariVoice':'aiJivanVoice',name=agent==='ZARI'?'Zari':'Jivan',voice=$(select)?.value||'',speed=Number($('aiVoiceSpeed')?.value||1);try{const audio=await synthesizeConnectedVoice(agent==='ZARI'?'Hello. I am Zari. I will guide you naturally and hand you over to Jivan when reception is complete.':'Hello. I am Jivan. I am ready to work with you in a calm, natural voice.',agent,voice,speed);if(audio?.url)await playVoiceUrl(audio.url);}catch(err){toast(err.message||`${name} voice preview is unavailable.`);}}
  function bindAiPreferenceUi(){const pane=$('controlPaneSettings');if(!pane||pane.dataset.aiPrefsBound==='true')return;pane.dataset.aiPrefsBound='true';pane.addEventListener('input',e=>{if(e.target.id==='aiTemperature'&&$('aiTemperatureValue'))$('aiTemperatureValue').textContent=Number(e.target.value||0).toFixed(2);if(e.target.id==='aiVoiceSpeed'&&$('aiVoiceSpeedValue'))$('aiVoiceSpeedValue').textContent=Number(e.target.value||1).toFixed(2)+'×';});pane.addEventListener('click',e=>{const p=e.target.closest('[data-ai-voice-preview]');if(p)return previewAiVoice(p.dataset.aiVoicePreview);if(e.target.closest('#saveAiPreferences'))return saveAiPreferences();});}
  function syncAiPreferenceVisibility(){const ai=$('settingsIntelligenceSection'),nav=document.querySelector('[data-settings-nav="intelligence"]');if(ai){ai.dataset.permissionHidden='false';if(settingsActivePage!=='intelligence')ai.hidden=true;}if(nav){nav.dataset.permissionHidden='false';nav.hidden=false;}bindAiPreferenceUi();if(settingsActivePage==='intelligence')loadAiPreferences();}
  async function styleAgentResponse(text,operator='JIVAN'){const source=agentDisplayText(text);if(!source||!browserSessionToken)return source;try{const r=await supabaseFunction('jivan-response-style',{text:source,operator});return agentDisplayText(r?.text||source);}catch{return source;}}
  async function announceZariHandoff(user=null){const name=String(user?.name||user?.id||'').trim(),line=`${name?`Welcome ${name}. `:''}Zari here. Access is confirmed. I will now hand you over to Jivan.`;setConnectedAiOperator('ZARI');let spoken=false;try{const audio=await synthesizeConnectedVoice(line,'ZARI');if(audio?.url)spoken=await playVoiceUrl(audio.url);}catch{}if(!spoken)await speakAuthPromptAwait(line);await sleep(520);setConnectedAiOperator('JIVAN');window.dispatchEvent(new CustomEvent('assurance-regent-agent-handoff',{detail:{from:'ZARI',to:'JIVAN',user:user||null,message:line}}));return line;}
  async function clearAllAiInbox(){if(!confirm('Clear all AI advisory conversations from your Inbox? Human conversations will stay.'))return;try{const r=await supabaseRpc('assurance_regent_browser_message_clear_all_ai',{p_token:browserSessionToken});if(state.activeInboxThread?.isAi)closeInboxThread();await loadInternalInbox(true);renderInternalInbox();renderControlDock();toast(`Cleared ${Number(r?.cleared||0)} AI message record${Number(r?.cleared||0)===1?'':'s'}.`);}catch(err){toast(err.message||'Could not clear AI advisories.');}}
  function directoryPersonKey(x){return String(x?.employeeId||x?.id||'').trim();}
  async function loadCompanyDirectoryHub(force=false){if(!browserSessionToken)return false;const company=activeCompanyForView(),key=String(company?.id||controlUser()?.companyId||'');if(!key)return false;if(!force&&companyDirectoryKey===key&&Array.isArray(state.companyDirectoryPeople))return false;if(companyDirectoryLoading)return false;companyDirectoryLoading=true;try{const b=await supabaseRpc('assurance_regent_browser_company_directory',{p_token:browserSessionToken,p_company_id:controlUser()?.role==='Developer'?key:''},{bypassCache:force});state.companyDirectoryPeople=Array.isArray(b?.people)?b.people.map(x=>({...x,employeeId:x.id,team:x.team||'General',active:'Yes'})):[];companyDirectoryKey=key;return true;}finally{companyDirectoryLoading=false;}}
  function combinedCompanyPeople(){const map=new Map();for(const e of (engine.state.employees||[])){if(directoryPersonKey(e))map.set(directoryPersonKey(e),{...e});}for(const u of (state.companyDirectoryPeople||[])){const k=directoryPersonKey(u);if(k)map.set(k,{...(map.get(k)||{}),...u,employeeId:k});}return [...map.values()];}
  function openCompanyPerson(id){const p=combinedCompanyPeople().find(x=>directoryPersonKey(x)===String(id));if(!p)return;const photo=safeProfilePhoto(p.profilePhoto),authority=p.supervisoryRole||p.position||p.role||'Employee';$('companyPersonDialogBody').innerHTML=`<div class="company-person-profile social-profile"><div class="company-person-profile-avatar">${photo?`<img src="${esc(photo)}" alt="${esc(p.name||id)}"/>`:esc(companyInitials(p.name||id))}</div><div><small>${esc(p.department||'Company directory')}</small><h2>${esc(p.name||id)}</h2><p>${esc(authority)}</p>${p.bio?`<span class="social-profile-bio">${esc(p.bio)}</span>`:''}</div></div><dl><div><dt>Employee ID</dt><dd>${esc(p.employeeId||p.id||'—')}</dd></div><div><dt>Position</dt><dd>${esc(p.position||'—')}</dd></div><div><dt>Department</dt><dd>${esc(p.department||'Unassigned')}</dd></div><div><dt>Team</dt><dd>${esc(p.team||'General')}</dd></div><div><dt>Email</dt><dd>${esc(p.email||'—')}</dd></div><div><dt>Phone</dt><dd>${esc(p.phone||'—')}</dd></div><div><dt>Workplace</dt><dd>${esc(p.workplace||'—')}</dd></div><div><dt>Work location</dt><dd>${esc(p.location||'—')}</dd></div><div><dt>Headquarters</dt><dd>${esc(p.headquarters||'—')}</dd></div><div><dt>Address</dt><dd>${esc(p.address||'—')}</dd></div></dl>`;if(!$('companyPersonDialog').open)$('companyPersonDialog').showModal();}
  /* Assurance Regent v6.3.40 — social Department Hub and editable directory profiles. */
  const SOCIAL_QUICK_REACTIONS=['❤️','👍','😂','🎉','👏','🙌'];
  let companySocialMediaHydrating=false;
  function companySocialPerson(id=''){const key=String(id||''),me=controlUser();if(me&&String(me.id||'')===key)return {...me,employeeId:me.id};return combinedCompanyPeople().find(x=>directoryPersonKey(x)===key)||{id:key,employeeId:key,name:key||'Colleague',department:'Company'};}
  function companySocialAvatar(person={},size='normal'){const photo=safeProfilePhoto(person.profilePhoto),name=person.name||person.id||'User';return `<span class="company-social-avatar ${size==='small'?'small':''}">${photo?`<img src="${esc(photo)}" alt="${esc(name)}"/>`:esc(companyInitials(name))}</span>`;}
  function companySocialTime(value){const t=Date.parse(value||'');if(!Number.isFinite(t))return '';const s=Math.max(0,Math.floor((Date.now()-t)/1000));if(s<60)return 'now';if(s<3600)return Math.floor(s/60)+'m';if(s<86400)return Math.floor(s/3600)+'h';if(s<604800)return Math.floor(s/86400)+'d';return formatDateTime(value);}
  function companySocialAttachments(list=[]){return (Array.isArray(list)?list:[]).map(a=>{const id=esc(a.fileId||''),name=esc(a.name||'Attachment'),mime=String(a.mimeType||'application/octet-stream');if(/^image\//i.test(mime))return `<button type="button" class="company-social-media image" data-company-social-media="${id}" data-media-kind="image" aria-label="Open ${name}"><span class="media-loading">Image · ${name}</span></button>`;if(/^video\//i.test(mime))return `<div class="company-social-media video" data-company-social-media="${id}" data-media-kind="video"><span class="media-loading">Video · ${name}</span></div>`;return `<button type="button" class="company-social-document" data-company-hub-file="${id}" data-company-hub-file-name="${encodeURIComponent(a.name||'document')}"><span>▧</span><b>${name}</b><small>Open document</small></button>`;}).join('');}
  /* Assurance Regent v6.3.46 — fast private Department Hub streaming. */
  const companySocialSignedCache=new Map();
  function companySocialTrimSignedCache(){while(companySocialSignedCache.size>120){const first=companySocialSignedCache.keys().next().value;if(first===undefined)break;companySocialSignedCache.delete(first);}}
  async function companySocialSignedFile(fileId){const id=String(fileId||'').trim();if(!id)throw new Error('Stored file reference is missing.');const now=Date.now(),hit=companySocialSignedCache.get(id);if(hit?.promise)return hit.promise;if(hit?.value&&Number(hit.expiresAt||0)>now+30000)return hit.value;const promise=persistentFileDownload(id).then(stored=>{const ttl=Math.max(60000,(Math.max(60,Number(stored?.expires_in||600))-45)*1000),entry={value:stored,expiresAt:Date.now()+ttl};companySocialSignedCache.set(id,entry);companySocialTrimSignedCache();return stored;}).catch(err=>{companySocialSignedCache.delete(id);throw err;});companySocialSignedCache.set(id,{promise,expiresAt:now+60000});return promise;}
  async function openCompanySocialFile(fileId,name='attachment'){const stored=await companySocialSignedFile(fileId),a=document.createElement('a');a.href=stored.url;a.target='_blank';a.rel='noopener';a.download=stored.name||name||'attachment';document.body.appendChild(a);a.click();a.remove();return stored;}
  async function hydrateCompanySocialMedia(){if(companySocialMediaHydrating)return;const nodes=[...document.querySelectorAll('[data-company-social-media]:not([data-media-ready])')];if(!nodes.length)return;companySocialMediaHydrating=true;try{const batch=nodes.slice(0,30);await Promise.allSettled(batch.map(async node=>{node.dataset.mediaReady='loading';try{const stored=await companySocialSignedFile(node.dataset.companySocialMedia),kind=node.dataset.mediaKind;if(kind==='image'){node.innerHTML='<img src="'+esc(stored.url)+'" alt="'+esc(stored.name||'Shared image')+'" loading="lazy" decoding="async"/>';node.dataset.companyHubFile=node.dataset.companySocialMedia;node.dataset.companyHubFileName=encodeURIComponent(stored.name||'image');}else if(kind==='video'){node.innerHTML='<video controls preload="metadata" playsinline src="'+esc(stored.url)+'"></video>';}node.dataset.mediaReady='true';}catch(err){node.innerHTML='<span class="media-loading">Media unavailable</span>';node.dataset.mediaReady='error';node.title=String(err?.message||'Could not load media.');}}));}finally{companySocialMediaHydrating=false;if(document.querySelector('[data-company-social-media]:not([data-media-ready])'))queueMicrotask(()=>hydrateCompanySocialMedia());}}
  function companySocialReactionButtons(post){const map=new Map((post.reactionSummary||[]).map(r=>[r.emoji,Number(r.count||0)]));return SOCIAL_QUICK_REACTIONS.map(e=>`<button type="button" class="social-reaction ${post.myReaction===e?'active':''}" data-social-react="${e}" data-social-post="${esc(post.id)}"><span>${e}</span>${map.get(e)?`<b>${map.get(e)}</b>`:''}</button>`).join('');}
  function companySocialReplyMarkup(reply){const p=companySocialPerson(reply.senderId);return `<article class="company-social-reply">${companySocialAvatar(p,'small')}<div><header><button type="button" data-company-person="${esc(directoryPersonKey(p))}"><b>${esc(p.name||reply.senderName||reply.senderId)}</b></button><span>${esc(p.position||p.department||'Colleague')} · ${companySocialTime(reply.createdAt)}</span></header><p>${esc(reply.content||'')}</p>${reply.attachments?.length?`<div class="company-social-media-grid compact">${companySocialAttachments(reply.attachments)}</div>`:''}</div></article>`;}
  function companySocialPostMarkup(post,replies=[]){const p=companySocialPerson(post.senderId),photo=companySocialAvatar(p),my=String(post.senderId||'')===String(controlUser()?.id||'');const visibleReplies=replies.slice(-3);return `<article class="company-social-post" data-social-post-card="${esc(post.id)}"><div class="company-social-post-main">${photo}<div class="company-social-post-body"><header><button type="button" class="social-author" data-company-person="${esc(directoryPersonKey(p))}"><b>${esc(my?'You':p.name||post.senderName||post.senderId)}</b><span>${esc(p.position||p.department||'Company member')}</span></button><time>${companySocialTime(post.createdAt)}</time></header><p class="social-post-copy">${esc(post.content||'')}</p>${post.attachments?.length?`<div class="company-social-media-grid ${post.attachments.length===1?'single':''}">${companySocialAttachments(post.attachments)}</div>`:''}<div class="social-post-actions"><div>${companySocialReactionButtons(post)}</div><button type="button" class="social-action" data-social-reply="${esc(post.id)}">↩ <span>Reply${post.replyCount?` · ${Number(post.replyCount)}`:''}</span></button></div>${visibleReplies.length?`<div class="company-social-replies">${visibleReplies.map(r=>companySocialCommentMarkup(r,post.id)).join('')}${replies.length>3?`<small class="social-more-replies">${replies.length-3} earlier repl${replies.length-3===1?'y':'ies'}</small>`:''}</div>`:''}</div></div></article>`;}
  function companySocialStatusMarkup(status){const p=companySocialPerson(status.senderId),photo=safeProfilePhoto(p.profilePhoto),label=String(status.content||'Status').slice(0,34);return `<button type="button" class="company-status-item" data-company-status="${esc(status.id)}"><span class="status-ring"><span>${photo?`<img src="${esc(photo)}" alt="${esc(p.name||status.senderName)}"/>`:esc(companyInitials(p.name||status.senderName||status.senderId))}</span></span><b>${esc(String(p.name||status.senderName||status.senderId).split(' ')[0])}</b><small>${esc(label||'Status')}</small></button>`;}


  function setCompanySocialMode(mode='POST',replyId=''){state.companyHubPostMode=mode;state.companyHubReplyTo=replyId||'';const pill=$('companyHubComposerMode');if(pill)pill.textContent=mode==='STATUS'?'Status · visible for 24 hours':mode==='REPLY'?'Replying to a post':'Post to '+(state.companyHubDepartment||'channel');const btn=$('companyHubPostSubmit');if(btn)btn.textContent=mode==='STATUS'?'Share status':mode==='REPLY'?'Reply':'Post';const input=$('companyHubInput');if(input){input.placeholder=mode==='STATUS'?'Share a status with your company…':mode==='REPLY'?'Write your reply…':`What's happening in ${state.companyHubDepartment||'your company'}?`;input.focus();}}
  function previewCompanySocialFiles(){return previewCompanySocialFiles53();}

  async function reactCompanySocial(postId,emoji){try{const company=activeCompanyForView(),companyId=String(company?.id||controlUser()?.companyId||'');await supabaseRpc('assurance_regent_browser_department_social_react',{p_token:browserSessionToken,p_message_id:postId,p_emoji:emoji,p_company_id:companyId},{bypassCache:true});await loadCompanyHubMessages(state.companyHubDepartment,true);}catch(err){toast(err.message||'Could not react to this post.');}}
  function openCompanyStatus(id){const s=(state.companyHubStatuses||[]).find(x=>String(x.id)===String(id));if(!s)return;const p=companySocialPerson(s.senderId),dlg=$('companyStatusDialog'),body=$('companyStatusDialogBody');if(!dlg||!body)return;body.innerHTML=`<div class="social-status-view"><header>${companySocialAvatar(p)}<div><b>${esc(p.name||s.senderName||s.senderId)}</b><small>${esc(p.position||p.department||'Company member')} · ${companySocialTime(s.createdAt)}</small></div></header><p>${esc(s.content||'')}</p>${s.attachments?.length?`<div class="company-social-media-grid single">${companySocialAttachments(s.attachments)}</div>`:''}</div>`;if(!dlg.open)dlg.showModal();queueMicrotask(()=>hydrateCompanySocialMedia());}


  /* Assurance Regent v6.3.48 — LinkedIn-style reactions, threaded comments and engagement analytics. */
