  function companyHubStoryCommentFormMarkup(root,parent,placeholder='Reply to status…',inline=false){return `<form class="company-hub-story-comment-form" data-company-story-comment-form data-story-root="${esc(root)}" data-story-parent="${esc(parent)}"><textarea rows="1" maxlength="6000" data-company-story-comment-input placeholder="${esc(placeholder)}" required></textarea><button type="button" class="emoji" data-company-story-comment-emoji-toggle>😊</button><button type="submit" class="submit">Post</button><div class="company-hub-story-comment-emoji-panel" hidden>${COMPANY_HUB_STORY_EMOJIS.map(e=>`<button type="button" data-company-story-comment-emoji="${esc(e)}">${esc(e)}</button>`).join('')}</div></form>`;}
