  function companyHubInlineKind54(att={}){const mime=String(att.mimeType||att.mime_type||'').toLowerCase(),ext=companyHubInlineExt54(att.name||att.original_name||'');if(mime.startsWith('audio/')||['mp3','wav','m4a','aac','ogg','oga','flac','opus'].includes(ext))return 'audio';if(mime.startsWith('video/')||['mp4','webm','mov','m4v','ogv'].includes(ext))return 'video';if(mime.startsWith('image/')||['png','jpg','jpeg','gif','webp','bmp','svg'].includes(ext))return 'image';if(mime==='application/pdf'||ext==='pdf')return 'pdf';if(['docx','doc'].includes(ext)||/wordprocessingml|msword/.test(mime))return 'word';if(['xlsx','xls'].includes(ext)||/spreadsheetml|excel/.test(mime))return 'sheet';if(['pptx','ppt'].includes(ext)||/presentationml|powerpoint/.test(mime))return 'slides';if(['txt','csv','md','json','xml','log','rtf'].includes(ext)||/^text\//.test(mime)||/json|xml/.test(mime))return 'text';return 'file';}
