  /* Assurance Regent v6.3.39 — Developer or company CEO administrator elevation. */
  function executiveAdministratorCanMakeAdmin(user=controlUser()||{}){
    if(String(user?.role||'')==='Developer')return true;
    if(String(user?.role||'')!=='Administrator')return false;
    const effective=effectiveUserOrg(user||{}),authority=functionalAuthority(effective),text=[effective?.supervisoryRole,effective?.position,effective?.department].filter(Boolean).join(' ').toLowerCase();
    return authority==='CEO'||/(^|[^a-z])(chief executive officer|ceo|country director|managing director|country partner)([^a-z]|$)/.test(text);
  }
  function renderDeveloperMakeAdminControl(users=[],isDev=false){
    const actor=controlUser()||{},canGrant=executiveAdministratorCanMakeAdmin(actor),actorCompany=String(actor.companyId||''),box=$('developerMakeAdminControls'),select=$('developerMakeAdminUser'),nav=document.querySelector('[data-settings-nav="access"]'),section=$('accessManagementSection');
    if(nav){nav.dataset.permissionHidden=canGrant?'false':'true';nav.hidden=!canGrant;}if(section)section.hidden=!canGrant||settingsActivePage!=='access';
    if(!box||!select)return;box.hidden=!canGrant;
    if(!canGrant){select.innerHTML='<option value="">Developer or company CEO permission required</option>';if(settingsActivePage==='access')showSettingsPage('general');return;}
    const current=select.value,eligible=(Array.isArray(users)?users:[]).filter(x=>{const role=String(x?.role||'Employee'),status=String(x?.approvalStatus||((x?.active===false)?'SUSPENDED':'APPROVED')).toUpperCase(),active=x?.active!==false&&String(x?.active??'true').toLowerCase()!=='false',company=String(x?.companyId||'').trim();return role==='Employee'&&status==='APPROVED'&&active&&Boolean(company)&&(isDev||company===actorCompany);});
    select.innerHTML='<option value="">Select user / username</option>'+eligible.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.id)+' — '+esc(x.name||x.id)+'</option>').join('');if(eligible.some(x=>String(x.id)===String(current)))select.value=current;
  }
  async function developerMakeAdminUi(){
    if(!executiveAdministratorCanMakeAdmin(controlUser()||{}))return toast('Developer or company CEO permission is required.');const id=$('developerMakeAdminUser')?.value||'';if(!id)return toast('Select a user / username first.');const target=(state.control?.profile?.users||[]).find(x=>String(x.id)===String(id));if(!target)return toast('The selected user could not be found.');
    if(!confirm('Make '+(target.name||target.id)+' an Administrator? This grants company-level administrative access.'))return;
    const btn=$('developerMakeAdminBtn'),label=btn?.textContent||'Make admin';try{if(btn){btn.disabled=true;btn.textContent='Assigning…';}const result=await supabaseRpc('assurance_regent_browser_developer_make_admin',{p_token:browserSessionToken,p_user_id:id});await loadStandaloneState();await refreshControlCenter();renderSettingsPane();showSettingsPage('access');toast(result?.alreadyAdministrator?(target.name||id)+' is already an Administrator.':(target.name||id)+' is now an Administrator.');}catch(err){toast(err.message);}finally{if(btn){btn.disabled=false;btn.textContent=label;}}
  }

  async function developerCreateAccountUi(){
    if(controlUser()?.role!=='Developer')return toast('Developer permission is required.');
    const payload={companyId:$('developerAccountCompany')?.value||'',role:$('developerAccountRole')?.value||'Employee',userId:$('developerAccountId')?.value.trim()||'',name:$('developerAccountName')?.value.trim()||'',position:$('developerAccountPosition')?.value.trim()||'',department:$('developerAccountDepartment')?.value.trim()||'',supervisoryRole:$('developerAccountAuthority')?.value||'',email:$('developerAccountEmail')?.value.trim()||'',password:$('developerAccountPassword')?.value||''};
    if(payload.role==='Developer')payload.companyId='';
    if((payload.role!=='Developer'&&!payload.companyId)||!payload.userId||!payload.name||!payload.position||payload.password.length<8)return toast('Username, name, position, password, and a company for non-Developer accounts are required.');
    try{await supabaseRpc('assurance_regent_browser_admin_upsert_user',{p_token:browserSessionToken,p_user_id:payload.userId,p_company_id:payload.companyId,p_name:payload.name,p_position:payload.position,p_email:payload.email,p_password:payload.password,p_role:payload.role});if(payload.role!=='Developer'&&(payload.department||payload.supervisoryRole))await supabaseRpc('assurance_regent_browser_admin_update_user',{p_token:browserSessionToken,p_user_id:payload.userId,p_role:payload.role,p_company_id:payload.companyId,p_position:payload.position,p_department:payload.department,p_supervisor:'',p_supervisory_role:payload.supervisoryRole});await loadStandaloneState();['developerAccountId','developerAccountName','developerAccountPosition','developerAccountDepartment','developerAccountEmail','developerAccountPassword'].forEach(id=>{if($(id))$(id).value='';});if($('developerAccountAuthority'))$('developerAccountAuthority').value='';toast(`${payload.role} account created and approved${payload.supervisoryRole?` with ${payload.supervisoryRole} authority`:''}.`);await refreshControlCenter();renderSettingsPane();}catch(err){toast(err.message);}
  }
  async function deleteUserAccountUi(){
    const id=$('accessUserSelect')?.value;if(!id)return toast('Select an account first.');if(controlUser()?.role!=='Developer')return toast('Developer permission is required.');if(!confirm('Delete this account? Existing operational records will retain their historical user references.'))return;
    try{await supabaseRpc('assurance_regent_browser_admin_delete_user',{p_token:browserSessionToken,p_user_id:id});await loadStandaloneState();toast('Account deleted.');await refreshControlCenter();renderSettingsPane();}catch(err){toast(err.message);}
  }
  async function createCompanyUi(){const name=$('newCompanyName')?.value.trim(),code=$('newCompanyCode')?.value.trim().toUpperCase(),countryCode=$('newCompanyCountry')?.value||'',countryRow=countryByCode(countryCode),meetUrl=normalizeGoogleMeetUrl($('newCompanyMeetUrl')?.value||'');if(!name||!code||!countryRow||!meetUrl)return toast('Enter a company name, code, registered country, and valid Google Meet interview room.');try{if(controlUser()?.role!=='Developer')throw new Error('Developer permission is required to create a company.');const auth=previewAuthData();if(auth.companies.some(c=>String(c.code).toUpperCase()===code))throw new Error('Company code already exists.');if(auth.companies.some(c=>normalizeGoogleMeetUrl(c.interviewMeetUrl)===meetUrl))throw new Error('That Google Meet room is already assigned to another company.');auth.companies.push({id:`COMP-${crypto.randomUUID()}`,name,code,registeredCountry:countryRow.country,registeredCountryCode:countryRow.countryCode,interviewMeetUrl:meetUrl,active:true,systemEnabled:true,monthlyAmount:0,billingCurrency:'USD',paymentAccount:'',billingMessage:'',createdAt:new Date().toISOString(),createdBy:controlActorId()});savePreviewAuthData(auth);await queueStandaloneSave();$('newCompanyName').value='';$('newCompanyCode').value='';$('newCompanyCountry').value='';$('newCompanyMeetUrl').value='';toast('Company created with its dedicated interview room.');await loadStandaloneState();await refreshControlCenter();renderSettingsPane();renderCompany();}catch(err){toast(err.message);}}
  async function updateCompanyAccessUi(companyId,fromToggle=false){if(controlUser()?.role!=='Developer'){toast('Developer permission is required.');return false;}const card=document.querySelector(`[data-company-card="${CSS.escape(companyId)}"]`);if(!card)return false;const enabled=Boolean(card.querySelector('[data-company-enabled]')?.checked),countryCode=card.querySelector('[data-company-registered-country]')?.value||'',storedCompany=companyById(companyId),countryRow=countryByCode(countryCode)||((storedCompany?.registeredCountry)?{country:storedCompany.registeredCountry,countryCode:storedCompany.registeredCountryCode||countryCode}:null),amount=Number(card.querySelector('[data-company-amount]')?.value||0),currency=card.querySelector('[data-company-currency]')?.value.trim().toUpperCase()||'USD',payment=card.querySelector('[data-company-payment]')?.value.trim()||'',message=card.querySelector('[data-company-message]')?.value.trim()||'',meetUrl=normalizeGoogleMeetUrl(card.querySelector('[data-company-meet-url]')?.value||'');if(!meetUrl){toast('Enter a valid Google Meet room for this company before saving.');return false;}if(!enabled&&!confirm('Switch this entire company offline? All Administrator and Employee access for this company will be blocked.'))return false;try{await supabaseRpc('assurance_regent_browser_admin_company_access',{p_token:browserSessionToken,p_company_id:companyId,p_enabled:enabled,p_monthly_amount:amount,p_currency:currency,p_payment_account:payment,p_billing_message:message});if(countryRow)await supabaseRpc('assurance_regent_browser_admin_company_registration',{p_token:browserSessionToken,p_company_id:companyId,p_country:countryRow.country,p_country_code:countryRow.countryCode});await supabaseRpc('assurance_regent_browser_admin_company_interview_room',{p_token:browserSessionToken,p_company_id:companyId,p_meet_url:meetUrl});await loadStandaloneState();toast(enabled?'Company access and interview room saved.':'Company access switched OFF; interview room setting preserved.');await refreshControlCenter();renderSettingsPane();return true;}catch(err){toast(err.message);return false;}}
  async function registerAgentReview(response){if(STANDALONE_MODE||!response?.requires_approval)return null;try{const r=await apiFetch('/api/control-center/reviews/agent',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({detail:(response.approvals||[]).map(a=>`${a.agent||'Agent'}: ${a.tool||'action'}`).join(' · '),approvalState:response.approval_state,sessionId:response.session_id||sessionId(),approvals:response.approvals||[]})}),b=await r.json();if(r.ok){response.control_review_id=b.id;await refreshControlCenter();return b;}}catch(err){console.warn(err);}return null;}
  async function clearAgentConversation(startNew=false){try{if(STANDALONE_MODE){await supabaseRpc('assurance_regent_browser_agent_clear',{p_token:browserSessionToken});}else{const r=await apiFetch(`/api/brain/thread?actor_id=${encodeURIComponent(controlActorId())}&start_new=${startNew?'true':'false'}`,{method:'DELETE'});if(!r.ok){const b=await r.json().catch(()=>({}));throw new Error(b.error||'Could not clear conversation.');}}$('chatMessages').innerHTML=developerStudioAllowed()?'<div class="agent-empty developer-holo-empty" id="agentEmptyState"><small>CHANNEL RESET // 00</small><b>Jivan core standing by</b><span>Previous dialogue cleared. Developer channel is ready for a new instruction.</span></div>':'<div class="agent-empty" id="agentEmptyState"><b>Fresh Jivan conversation</b><span>Your previous chat has been cleared. Give Jivan a new instruction whenever you are ready.</span></div>';if(developerStudioAllowed())setJivanHoloState('idle','Dialogue buffer cleared. Awaiting developer instruction.',0,{step:'CHANNEL RESET'});if($('chatInput'))$('chatInput').value='';hidePredictiveCompose();pendingApproval=null;state.agentLastReply='';state.agentLastAction='';state.agentRoleProfile=null;state.agentLastDocument=null;state.agentPendingUploadTarget='';if($('approvalDialog')?.open)$('approvalDialog').close();window.dispatchEvent(new CustomEvent('assurance-regent-agent-thread-reset',{detail:{reason:startNew?'new':'clear'}}));toast(startNew?'New Jivan conversation started.':'Jivan conversation cleared.');await refreshControlCenter();return true;}catch(err){toast(err.message);throw err;}}

  async function exportData(kind){let rows=[];if(kind==='monthly'||kind==='engine')rows=engine.monthlyEngine();if(kind==='projects')rows=engine.state.projects;if(kind==='employees')rows=engine.state.employees;if(kind==='vacancies')rows=engine.state.vacancies;if(kind==='candidates')rows=engine.state.candidates;if(kind==='onboarding')rows=engine.state.onboarding;if(!rows.length)return toast('No live records are available to export.');const headers=Object.keys(rows[0]);const csv=[headers.join(','),...rows.map(r=>headers.map(h=>`"${String(r[h]??'').replaceAll('"','""')}"`).join(','))].join('\n'),name=`adra-${kind}.csv`,blob=new Blob([csv],{type:'text/csv'});try{await uploadPersistentBlob(blob,name,{category:'data-exports',entityType:'data-export',entityId:kind});}catch(err){return toast(err.message||'Could not persist export.');}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href);}
  function toast(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600);}
  function debounce(fn,ms){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms);};}

  /* Dependency-free canvas charts */
  function prepCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(500,rect.width*dpr);canvas.height=280*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);return {c,w:canvas.width/dpr,h:280};}
  function drawEmptyChart(canvas,message='Waiting for live data'){if(!canvas)return;const {c,w,h}=prepCanvas(canvas);c.clearRect(0,0,w,h);c.save();c.fillStyle='#71808a';c.textAlign='center';c.textBaseline='middle';c.font='600 14px Inter, system-ui, sans-serif';c.fillText(message,w/2,h/2);c.restore();}
  function axes(c,w,h,pad,min,max,labels,suffix=''){c.clearRect(0,0,w,h);c.strokeStyle='#e3ecef';c.fillStyle='#78909b';c.lineWidth=1;c.font='9px system-ui';for(let i=0;i<=4;i++){const y=pad.t+(h-pad.t-pad.b)*(i/4);c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();const v=max-(max-min)*(i/4);c.fillText(`${compact(v)}${suffix}`,4,y+3);}labels.forEach((x,i)=>{const cx=pad.l+(w-pad.l-pad.r)*(labels.length===1?.5:i/(labels.length-1||1));c.fillText(x,cx-16,h-8);});}
  function compact(v){const a=Math.abs(v);if(a>=1e6)return `${(v/1e6).toFixed(1)}m`;if(a>=1e3)return `${(v/1e3).toFixed(0)}k`;return `${Math.round(v)}`;}
  function drawLines(canvas,labels,series,opt={}){if(!canvas)return;const {c,w,h}=prepCanvas(canvas),pad={l:45,r:14,t:28,b:30};let vals=series.flatMap(s=>s.values).filter(Number.isFinite),min=opt.min??Math.min(0,...vals),max=opt.max??Math.max(...vals);if(max===min)max=min+1;axes(c,w,h,pad,min,max,labels,opt.suffix||'');series.forEach(s=>{c.strokeStyle=s.color;c.fillStyle=s.color;c.lineWidth=2.3;c.beginPath();s.values.forEach((v,i)=>{const x=pad.l+(w-pad.l-pad.r)*(i/(labels.length-1||1)),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();s.values.forEach((v,i)=>{const x=pad.l+(w-pad.l-pad.r)*(i/(labels.length-1||1)),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.fill();});});drawLegend(c,series,w);}
  function drawGroupedBars(canvas,labels,series,opt={}){if(!canvas)return;const vals=series.flatMap(s=>s.values).filter(Number.isFinite);if(!labels.length||!vals.length)return drawEmptyChart(canvas,'Waiting for live data');const {c,w,h}=prepCanvas(canvas),pad={l:50,r:14,t:32,b:32};let min=Math.min(0,...vals),max=Math.max(...vals);if(max===min)max=min+1;axes(c,w,h,pad,min,max,labels);const area=w-pad.l-pad.r,group=area/labels.length,bw=Math.max(3,Math.min(18,(group-12)/series.length));series.forEach((s,si)=>{c.fillStyle=s.color;s.values.forEach((v,i)=>{const zero=pad.t+(max)/(max-min)*(h-pad.t-pad.b),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b),x=pad.l+i*group+group/2-(series.length*bw)/2+si*bw;c.fillRect(x,Math.min(y,zero),bw-2,Math.abs(zero-y));});});drawLegend(c,series,w);}
  function drawHorizontalBars(canvas,labels,values,color,opt={}){if(!canvas)return;const hasPeople=Array.isArray(opt.people)&&opt.people.length>0,{c,w,h}=prepCanvas(canvas),pad={l:hasPeople?128:95,r:35,t:24,b:18};c.clearRect(0,0,w,h);const min=Math.min(0,...values),max=Math.max(0,...values),range=(max-min)||1,barH=Math.min(18,(h-pad.t-pad.b)/Math.max(labels.length,1)-5);c.font='9px system-ui';labels.forEach((lab,i)=>{const y=pad.t+i*((h-pad.t-pad.b)/labels.length),person=hasPeople?opt.people[i]:null,photo=safeProfilePhoto(person?.profilePhoto),textX=hasPeople?29:5;c.fillStyle='#637b87';c.fillText(lab,textX,y+barH*.75);if(hasPeople){c.save();c.beginPath();c.arc(14,y+barH/2,9,0,Math.PI*2);c.clip();c.fillStyle='#d7edf5';c.fillRect(5,y+barH/2-9,18,18);c.restore();if(photo){const img=new Image();img.onload=()=>{c.save();c.beginPath();c.arc(14,y+barH/2,9,0,Math.PI*2);c.clip();c.drawImage(img,5,y+barH/2-9,18,18);c.restore();};img.src=photo;}else{c.fillStyle='#385d6d';c.font='bold 6px system-ui';c.textAlign='center';c.fillText(companyInitials(lab),14,y+barH/2+2);c.textAlign='start';c.font='9px system-ui';}}const zero=pad.l+(-min/range)*(w-pad.l-pad.r),x=pad.l+((values[i]-min)/range)*(w-pad.l-pad.r);c.strokeStyle='#e4ecef';c.beginPath();c.moveTo(pad.l,y+barH+4);c.lineTo(w-pad.r,y+barH+4);c.stroke();c.fillStyle=color;c.fillRect(Math.min(zero,x),y,Math.max(2,Math.abs(x-zero)),barH);c.fillStyle='#425b67';c.fillText(num(values[i],1),Math.min(w-pad.r-25,Math.max(zero,x)+5),y+barH*.75);});}
  function drawLegend(c,series,w){let x=w-12;[...series].reverse().forEach(s=>{const tw=c.measureText(s.label).width;x-=tw+22;c.fillStyle=s.color;c.fillRect(x,8,8,8);c.fillStyle='#637b87';c.fillText(s.label,x+12,15);x-=8;});}

  window.AssuranceRegentAgentBridge={
    version:RECOVERY_AGENT_VERSION,
    send:(text,options={})=>handleAgentMessage(text,options),
    invoke:(payload={})=>supabaseFunction('recovery-agent',payload),
    getContext:()=>agentPageContext(),
    getUser:()=>{const u=effectiveUserOrg(controlUser()||{});return u?.id?{id:u.id||'',name:u.name||'',email:u.email||'',role:u.role||'',position:u.position||'',department:u.department||'',supervisor:u.supervisor||'',supervisoryRole:u.supervisoryRole||'',authority:functionalAuthority(u),companyId:u.companyId||''}:null;},
    getPermissions:()=>({...controlPermissions()}),
    synthesizeVoice:(text,agent='JIVAN',voice='')=>synthesizeConnectedVoice(text,agent,voice),
    executeUiActions:(actions)=>executeAgentUiActions(actions),
    navigate:(view)=>executeAgentUiActions([{type:'navigate',target:view}]),
    openPanel:(panel)=>executeAgentUiActions([{type:'control_panel',panel}]),
    clearConversation:(startNew=false)=>clearAgentConversation(startNew),
    minimize:()=>minimizeJivanInterface(),
    requestUpload:(instruction='',options={})=>requestAgentUploadFromInstruction(instruction,options),
    openUploadTarget:(target='recovery_agent',wanted='',options={})=>openAgentUploadTarget(target,wanted,options),
    isUploadInstruction:(instruction='')=>explicitUploadFileCommand(instruction),
    loadThread:()=>loadBrainThread(),
    showMessage:(text,label='Jivan notification')=>addMessage('assistant',String(text||''),false,label),
    getNotifications:()=>({count:(state.control?.notifications||[]).length,items:(state.control?.notifications||[]).slice(0,12)}),
    analyzeUpload:(file)=>analyzeAgentUpload(file),
    openAgent:()=>developerStudioAllowed()?switchView('assistant'):false,
    openLeave:()=>switchView('leave'),
    getLeave:()=>({requests:state.leaveRequests||[],statuses:state.workStatuses||[],policies:state.leavePolicies||[]}),
    getBackgroundTasks:()=>Array.isArray(state.agentBackgroundTasks)?state.agentBackgroundTasks:[],
    refreshBackgroundTasks:()=>loadJivanTasks(),
    startBackgroundTasks:()=>startJivanBackgroundWorker(),
    delegateBackgroundTask:(instruction,title='Jivan delegated task',priority='NORMAL')=>queueJivanTask({instruction,title,priority}),
    openBackgroundTasks:()=>{if(!developerStudioAllowed())return false;switchView('assistant');jivanTaskPanelOpen=true;renderJivanTasks();loadJivanTasks().catch(()=>{});return true;}
  };
  window.dispatchEvent(new Event('assurance-regent-agent-ready'));

  boot().catch(err=>{
    console.error('Assurance Regent startup failed.',err);
    try{forgetBrowserSession();state.control=defaultLocalControl();applyAccessControl();ensureAuthEntryVisible();}
    catch(authErr){console.error('Assurance Regent authentication recovery failed.',authErr);}
  });
